-- =====================================================================
--  Raqam (رَقَم) — PostgreSQL 16 schema
--  00 · Foundation: extensions, shared functions, domains
-- =====================================================================
--  Normal form target: 3NF (BCNF wherever practical).
--  Conventions
--    * Surrogate keys: bigint/integer/smallint GENERATED BY DEFAULT AS IDENTITY.
--    * Natural keys for stable reference data (ISO currency codes, status codes).
--    * All timestamps are timestamptz (stored UTC, shown in Asia/Hebron).
--    * Money = bigint minor units (agorot/cents) + currency_code FK.
--    * No derived/aggregated values are stored in entity tables; they live
--      in views, materialized views or explicit daily aggregate tables.
--    * Polymorphic "model_type/model_id" pairs are avoided (no FK possible);
--      explicit nullable FKs + CHECK(num_nonnulls(...)) are used instead.
--      The only exception is audit_log.subject_* (a log must outlive rows).
-- =====================================================================

CREATE EXTENSION IF NOT EXISTS citext;      -- case-insensitive e-mails
CREATE EXTENSION IF NOT EXISTS pg_trgm;     -- fallback fuzzy search (FR 10.11)
CREATE EXTENSION IF NOT EXISTS btree_gist;  -- EXCLUDE constraints on scalar + range

-- ---------------------------------------------------------------------
--  Domains: one definition of a rule, reused by every column
-- ---------------------------------------------------------------------

-- Arabic-friendly URL slug: no spaces / reserved URL chars, no tashkeel, lower-case Latin.
CREATE DOMAIN slug_text AS varchar(200)
  CHECK (VALUE ~ '^[^[:space:]/?#%&]+$'
         AND VALUE !~ '[ً-ْٰ]'
         AND VALUE = lower(VALUE));

CREATE DOMAIN email_address AS citext
  CHECK (VALUE ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' AND length(VALUE) <= 254);

-- International phone format, e.g. +970599123456
CREATE DOMAIN phone_e164 AS varchar(16)
  CHECK (VALUE ~ '^\+[1-9][0-9]{6,14}$');

CREATE DOMAIN url_text AS varchar(2048)
  CHECK (VALUE ~* '^https?://[^[:space:]]+$');

CREATE DOMAIN hex_color AS char(7)
  CHECK (VALUE ~ '^#[0-9A-Fa-f]{6}$');

-- HMAC-SHA256 hex digest (IP addresses, tokens, device fingerprints are never stored raw)
CREATE DOMAIN sha256_hex AS char(64)
  CHECK (VALUE ~ '^[0-9a-f]{64}$');

-- Amounts in minor units (1 ILS = 100 agorot)
CREATE DOMAIN money_minor AS bigint
  CHECK (VALUE >= 0);

-- 100 basis points = 1 %
CREATE DOMAIN basis_points AS integer
  CHECK (VALUE BETWEEN 0 AND 10000);

-- ---------------------------------------------------------------------
--  Arabic search normalisation (decision 10.2)
--  Meilisearch's tokenizer splits «ال» and removes diacritics, but does not
--  unify letter variants. This function is the single definition; the PHP
--  class App\Support\ArabicNormalizer mirrors it exactly (parity-tested), and
--  both the search index and the PostgreSQL fallback search use it.
--    * lower-case Latin
--    * remove tashkeel (U+064B–U+065F), superscript alef (U+0670), tatweel (U+0640)
--    * أ إ آ ٱ → ا   ة → ه   ى → ي   ؤ → و   ئ → ي
--    * Arabic-Indic and Persian digits → 0-9
--    * collapse whitespace
-- ---------------------------------------------------------------------
CREATE FUNCTION normalize_ar(p text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
  SELECT btrim(regexp_replace(
           translate(
             regexp_replace(lower(p), '[ً-ٰٟـ]', '', 'g'),
             'أإآٱةىؤئ٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹',
             'ااااهيوي01234567890123456789'),
           '[[:space:]]+', ' ', 'g'));
$$;

-- ---------------------------------------------------------------------
--  Shared trigger functions
-- ---------------------------------------------------------------------

-- Keeps updated_at correct even if a query forgets it.
CREATE FUNCTION trg_set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- Gap-free yearly counters for human-readable numbers (bookings, invoices).
-- A sequence can skip numbers after a rollback; invoices legally must not.
CREATE TABLE document_counters (
  doc_type    varchar(16) NOT NULL CHECK (doc_type IN ('booking', 'invoice')),
  year        smallint    NOT NULL CHECK (year BETWEEN 2024 AND 2200),
  last_value  integer     NOT NULL CHECK (last_value >= 0),
  PRIMARY KEY (doc_type, year)
);

CREATE FUNCTION next_document_number(p_type varchar, p_year smallint) RETURNS integer
LANGUAGE sql AS $$
  INSERT INTO document_counters AS dc (doc_type, year, last_value)
  VALUES (p_type, p_year, 1)
  ON CONFLICT (doc_type, year) DO UPDATE SET last_value = dc.last_value + 1
  RETURNING last_value;
$$;

-- Local (Palestine) calendar year
CREATE FUNCTION local_year() RETURNS smallint
LANGUAGE sql STABLE AS $$
  SELECT extract(year FROM now() AT TIME ZONE 'Asia/Hebron')::smallint;
$$;

-- ---------------------------------------------------------------------
--  Laravel queue bookkeeping (the queued jobs themselves live in Redis)
--  Column names follow what Laravel's DatabaseUuidFailedJobProvider and
--  DatabaseBatchRepository read and write. payload, exception,
--  failed_job_ids and options are opaque framework data (serialized jobs,
--  stack traces) that are never queried field by field: a documented
--  exception to the "no JSON bags" rule, like payment_events.payload.
--  A failed job can carry personal data (e.g. a subscriber's e-mail), so
--  rows older than 30 days are pruned by the scheduler (queue:prune-failed).
-- ---------------------------------------------------------------------
CREATE TABLE failed_jobs (
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  uuid        uuid        NOT NULL UNIQUE,
  connection  text        NOT NULL,
  queue       text        NOT NULL,
  payload     text        NOT NULL,
  exception   text        NOT NULL,
  failed_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX failed_jobs_failed_at_idx ON failed_jobs (failed_at);   -- 30-day pruning

-- Laravel writes batch times as Unix seconds; bigint avoids the year-2038 limit.
CREATE TABLE job_batches (
  id              uuid    PRIMARY KEY,
  name            text    NOT NULL,
  total_jobs      integer NOT NULL CHECK (total_jobs >= 0),
  pending_jobs    integer NOT NULL CHECK (pending_jobs >= 0),
  failed_jobs     integer NOT NULL CHECK (failed_jobs >= 0),
  failed_job_ids  text    NOT NULL,
  options         text,
  cancelled_at    bigint,
  created_at      bigint  NOT NULL,
  finished_at     bigint
);
-- =====================================================================
--  01 · Identity & access: users, roles, verification codes, devices
--  Decisions: 2.4 (admin e-mail code), 2.5/17 (dormant customer accounts),
--             2.7 (roles founded, one used), 2.8 (one users table), 22.16
-- =====================================================================

CREATE TABLE users (
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_type          varchar(10)   NOT NULL CHECK (user_type IN ('staff', 'customer')),
  name               varchar(120)  NOT NULL,
  email              email_address NOT NULL,
  phone              phone_e164,
  password_hash      varchar(255)  NOT NULL,             -- Argon2id
  email_verified_at  timestamptz,
  is_active          boolean       NOT NULL DEFAULT true,
  remember_token     varchar(100),
  created_at         timestamptz   NOT NULL DEFAULT now(),
  updated_at         timestamptz   NOT NULL DEFAULT now(),
  deleted_at         timestamptz
);
-- One live account per e-mail; a deleted (anonymised) account frees the address.
CREATE UNIQUE INDEX users_email_live_uq ON users (email) WHERE deleted_at IS NULL;
COMMENT ON TABLE users IS 'Staff (admin) and dormant customer accounts. Last login is derived from login_attempts, not stored here.';

-- RBAC (dormant beyond the single admin role, decision 2.7)
CREATE TABLE roles (
  id         smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code       varchar(40) NOT NULL UNIQUE CHECK (code ~ '^[a-z_]+$'),
  name_ar    varchar(80) NOT NULL,
  is_system  boolean     NOT NULL DEFAULT false
);

CREATE TABLE permissions (
  id       smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code     varchar(80)  NOT NULL UNIQUE CHECK (code ~ '^[a-z_]+\.[a-z_]+$'),  -- module.action
  name_ar  varchar(120) NOT NULL
);

CREATE TABLE role_permissions (
  role_id        smallint NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
  permission_id  smallint NOT NULL REFERENCES permissions (id) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_id)
);
CREATE INDEX role_permissions_permission_idx ON role_permissions (permission_id);

CREATE TABLE user_roles (
  user_id  bigint   NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role_id  smallint NOT NULL REFERENCES roles (id) ON DELETE RESTRICT,
  PRIMARY KEY (user_id, role_id)
);
CREATE INDEX user_roles_role_idx ON user_roles (role_id);

-- Only staff may hold roles (cross-table rule => trigger).
CREATE FUNCTION trg_user_roles_staff_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = NEW.user_id AND user_type = 'staff') THEN
    RAISE EXCEPTION 'Only staff users can hold roles (user %)', NEW.user_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER user_roles_staff_only
  BEFORE INSERT OR UPDATE ON user_roles
  FOR EACH ROW EXECUTE FUNCTION trg_user_roles_staff_only();

-- One table for every 6-digit e-mail code (decisions 2.2, 2.4, 17.3, 17.5, 19.2)
CREATE TABLE verification_codes (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  purpose      varchar(20)   NOT NULL
               CHECK (purpose IN ('admin_login', 'newsletter_confirm', 'account_verify', 'password_reset')),
  email        email_address NOT NULL,
  code_hash    varchar(255)  NOT NULL,                 -- hashed, never the plain code
  attempts     smallint      NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 5),
  expires_at   timestamptz   NOT NULL,
  consumed_at  timestamptz,
  created_at   timestamptz   NOT NULL DEFAULT now(),
  CHECK (expires_at > created_at),
  CHECK (consumed_at IS NULL OR consumed_at >= created_at)
);
CREATE INDEX verification_codes_open_idx
  ON verification_codes (purpose, email, created_at DESC) WHERE consumed_at IS NULL;
CREATE INDEX verification_codes_expiry_idx ON verification_codes (expires_at);  -- pruning

-- Known devices per user => "new device" alert (2.4)
CREATE TABLE user_devices (
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id        bigint      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  device_hash    sha256_hex  NOT NULL,
  user_agent     varchar(512),
  first_seen_at  timestamptz NOT NULL DEFAULT now(),
  last_seen_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, device_hash),
  CHECK (last_seen_at >= first_seen_at)
);

-- Every admin/customer login attempt (22.16)
CREATE TABLE login_attempts (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email           email_address NOT NULL,
  user_id         bigint REFERENCES users (id) ON DELETE SET NULL,
  succeeded       boolean     NOT NULL,
  failure_reason  varchar(16)
                  CHECK (failure_reason IN ('bad_credentials', 'bad_code', 'expired_code', 'throttled', 'inactive')),
  device_hash     sha256_hex,
  ip_hash         sha256_hex,
  attempted_at    timestamptz NOT NULL DEFAULT now(),
  CHECK (succeeded = (failure_reason IS NULL))
);
CREATE INDEX login_attempts_user_idx  ON login_attempts (user_id, attempted_at DESC);
CREATE INDEX login_attempts_email_idx ON login_attempts (email, attempted_at DESC);
-- =====================================================================
--  02 · Media library (decision 9)
--  One row per uploaded file; generated sizes/formats in media_variants.
--  Alt text, caption, credit and focal point are typed columns (1NF),
--  not a JSON "custom_properties" bag.
-- =====================================================================

CREATE TABLE media_assets (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  visibility        varchar(8)   NOT NULL DEFAULT 'public' CHECK (visibility IN ('public', 'private')),
  disk              varchar(8)   NOT NULL DEFAULT 'local'  CHECK (disk IN ('local', 'r2')),   -- 9.10
  path              varchar(500) NOT NULL,                  -- random file name (9.8)
  original_name     varchar(255) NOT NULL,
  mime_type         varchar(40)  NOT NULL CHECK (mime_type IN (
                      'image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/svg+xml',
                      'video/mp4', 'application/pdf', 'application/x-rive')),               -- 9.7
  size_bytes        bigint       NOT NULL CHECK (size_bytes > 0),
  checksum_sha256   sha256_hex   NOT NULL,
  width             integer      CHECK (width  > 0),
  height            integer      CHECK (height > 0),
  duration_seconds  numeric(7,2) CHECK (duration_seconds > 0),
  alt_text          varchar(250),
  caption           varchar(500),
  credit            varchar(200),
  focal_x           numeric(4,3) CHECK (focal_x BETWEEN 0 AND 1),                            -- 9.5
  focal_y           numeric(4,3) CHECK (focal_y BETWEEN 0 AND 1),
  uploaded_by       bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at        timestamptz  NOT NULL DEFAULT now(),
  updated_at        timestamptz  NOT NULL DEFAULT now(),
  deleted_at        timestamptz,
  UNIQUE (disk, path),
  CHECK ((focal_x IS NULL) = (focal_y IS NULL)),
  -- Dimensions: both or neither, for every type
  CHECK ((width IS NULL) = (height IS NULL)),
  -- Raster images and video need dimensions (no layout shift; ffprobe reads them with
  -- the duration). SVG and Rive are exempt.
  CHECK (mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp', 'image/avif', 'video/mp4')
         OR width IS NOT NULL),
  -- 9.2: alt text is mandatory for every public raster/vector image
  CHECK (mime_type NOT LIKE 'image/%' OR visibility = 'private' OR alt_text IS NOT NULL),
  -- 9.9: size limits (stored file, after compression)
  CHECK (mime_type NOT LIKE 'image/%'      OR size_bytes <= 10 * 1024 * 1024),
  CHECK (mime_type <> 'application/pdf'    OR size_bytes <= 20 * 1024 * 1024),
  -- 8.11: short uploaded clips up to 90 s and 30 MB
  CHECK (mime_type <> 'video/mp4' OR (size_bytes <= 30 * 1024 * 1024
                                      AND duration_seconds IS NOT NULL AND duration_seconds <= 90))
);
CREATE INDEX media_assets_checksum_idx ON media_assets (checksum_sha256);
CREATE INDEX media_assets_recent_idx   ON media_assets (created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX media_assets_uploader_idx ON media_assets (uploaded_by);

-- Responsive renditions (9.3, 9.4): e.g. (42, 'md', 'avif')
CREATE TABLE media_variants (
  media_id    bigint       NOT NULL REFERENCES media_assets (id) ON DELETE CASCADE,
  variant     varchar(8)   NOT NULL CHECK (variant IN ('thumb', 'sm', 'md', 'lg', 'xl', 'og')),
  format      varchar(5)   NOT NULL CHECK (format IN ('avif', 'webp', 'jpeg', 'png')),
  width       integer      NOT NULL CHECK (width  > 0),
  height      integer      NOT NULL CHECK (height > 0),
  path        varchar(500) NOT NULL,
  size_bytes  bigint       NOT NULL CHECK (size_bytes > 0),
  PRIMARY KEY (media_id, variant, format)
);
-- =====================================================================
--  03 · Reference data & platform configuration
--  currencies, cities, sectors, organizations, social platforms,
--  SEO metadata, data providers, settings, feature flags
-- =====================================================================

-- ISO 4217. Every money column in the schema references this table.
CREATE TABLE currencies (
  code         char(3)     PRIMARY KEY CHECK (code ~ '^[A-Z]{3}$'),
  name_ar      varchar(60) NOT NULL UNIQUE,
  symbol       varchar(8)  NOT NULL,
  minor_units  smallint    NOT NULL DEFAULT 2 CHECK (minor_units BETWEEN 0 AND 4)
);

CREATE TABLE cities (
  id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name_ar    varchar(80)  NOT NULL UNIQUE,
  slug       slug_text    NOT NULL UNIQUE,
  latitude   numeric(9,6) NOT NULL CHECK (latitude  BETWEEN -90  AND 90),
  longitude  numeric(9,6) NOT NULL CHECK (longitude BETWEEN -180 AND 180)
);

CREATE TABLE sectors (
  id          smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name_ar     varchar(80) NOT NULL UNIQUE,
  slug        slug_text   NOT NULL UNIQUE,
  sort_order  integer     NOT NULL DEFAULT 0
);

-- Companies, factories, NGOs, advertisers, sponsors, initiative organisers.
-- Extracted so a company name/sector/city is stored once (3NF).
CREATE TABLE organizations (
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name           varchar(160) NOT NULL,
  slug           slug_text    NOT NULL UNIQUE,
  sector_id      smallint REFERENCES sectors (id) ON DELETE SET NULL,
  city_id        integer  REFERENCES cities (id)  ON DELETE SET NULL,
  founded_year   smallint CHECK (founded_year BETWEEN 1700 AND 2200),
  website        url_text,
  logo_media_id  bigint REFERENCES media_assets (id) ON DELETE SET NULL,
  search_name    text GENERATED ALWAYS AS (normalize_ar(name)) STORED,   -- derived, DB-maintained
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX organizations_search_trgm ON organizations USING gin (search_name gin_trgm_ops);
CREATE INDEX organizations_sector_idx ON organizations (sector_id);
CREATE INDEX organizations_city_idx   ON organizations (city_id);

CREATE TABLE social_platforms (
  code     varchar(16) PRIMARY KEY CHECK (code ~ '^[a-z]+$'),
  name     varchar(40) NOT NULL,
  sort_order integer   NOT NULL DEFAULT 0
);

-- Optional SEO overrides; referenced 1:1 (UNIQUE FK) by posts, categories, pages, ...
CREATE TABLE seo_meta (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  meta_title        varchar(70),
  meta_description  varchar(170),
  canonical_url     url_text,
  robots_noindex    boolean NOT NULL DEFAULT false,
  share_media_id    bigint REFERENCES media_assets (id) ON DELETE SET NULL,
  updated_at        timestamptz NOT NULL DEFAULT now()
);

-- External data providers (11, 12, 8, 19, 20) — switchable without code changes.
CREATE TABLE data_providers (
  code       varchar(32) PRIMARY KEY CHECK (code ~ '^[a-z0-9_]+$'),
  service    varchar(12) NOT NULL CHECK (service IN ('currency', 'weather', 'video', 'email', 'newsletter')),
  name       varchar(60) NOT NULL,
  is_active  boolean     NOT NULL DEFAULT false,
  is_backup  boolean     NOT NULL DEFAULT false
);
-- Exactly one active primary provider per service (partial unique index).
CREATE UNIQUE INDEX data_providers_one_primary_uq
  ON data_providers (service) WHERE is_active AND NOT is_backup;

CREATE TABLE provider_health (
  provider_code         varchar(32) PRIMARY KEY REFERENCES data_providers (code) ON DELETE CASCADE,
  last_success_at       timestamptz,
  last_failure_at       timestamptz,
  consecutive_failures  integer     NOT NULL DEFAULT 0 CHECK (consecutive_failures >= 0),
  last_error            varchar(1000),
  updated_at            timestamptz NOT NULL DEFAULT now()
);

-- Typed key/value site settings (21.13). Secrets never live here (.env only).
CREATE TABLE settings (
  key         varchar(80) PRIMARY KEY CHECK (key ~ '^[a-z_]+\.[a-z0-9_]+$'),   -- group.name
  value       text,
  value_type  varchar(8)  NOT NULL
              CHECK (value_type IN ('string', 'text', 'integer', 'boolean', 'url', 'email', 'phone', 'time', 'media')),
  updated_by  bigint REFERENCES users (id) ON DELETE SET NULL,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CHECK (value IS NULL OR value_type <> 'integer' OR value ~ '^-?[0-9]+$'),
  CHECK (value IS NULL OR value_type <> 'boolean' OR value IN ('true', 'false')),
  CHECK (value IS NULL OR value_type <> 'url'     OR value ~* '^https?://'),
  CHECK (value IS NULL OR value_type <> 'time'    OR value ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  CHECK (value IS NULL OR value_type <> 'media'   OR value ~ '^[0-9]+$'),
  -- e-mail and phone reuse the domains, so each format rule lives in one place
  CHECK (value IS NULL OR value_type <> 'email'   OR value::email_address IS NOT NULL),
  CHECK (value IS NULL OR value_type <> 'phone'   OR value::phone_e164 IS NOT NULL)
);

-- The platform's own social accounts (one row per platform, not one column each).
CREATE TABLE site_social_links (
  platform_code  varchar(16) PRIMARY KEY REFERENCES social_platforms (code) ON DELETE CASCADE,
  url            url_text    NOT NULL,
  sort_order     integer     NOT NULL DEFAULT 0,
  is_visible     boolean     NOT NULL DEFAULT true
);

-- Feature switches (21.14): booking, payments, accounts, chatbot, popup ad ...
CREATE TABLE feature_flags (
  key             varchar(32)  PRIMARY KEY CHECK (key ~ '^[a-z_]+$'),
  description_ar  varchar(200) NOT NULL,
  is_enabled      boolean      NOT NULL DEFAULT false,
  depends_on      varchar(32)  REFERENCES feature_flags (key) ON DELETE RESTRICT,
  updated_by      bigint REFERENCES users (id) ON DELETE SET NULL,
  updated_at      timestamptz  NOT NULL DEFAULT now(),
  CHECK (depends_on IS DISTINCT FROM key)
);

-- A child flag cannot be on while its parent is off (e.g. payments needs booking, 16.1).
CREATE FUNCTION trg_feature_flags_dependency() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.is_enabled AND NEW.depends_on IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM feature_flags WHERE key = NEW.depends_on AND is_enabled) THEN
    RAISE EXCEPTION 'Feature "%" requires "%" to be enabled first', NEW.key, NEW.depends_on
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT NEW.is_enabled
     AND EXISTS (SELECT 1 FROM feature_flags WHERE depends_on = NEW.key AND is_enabled) THEN
    RAISE EXCEPTION 'Disable the features that depend on "%" first', NEW.key
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER feature_flags_dependency
  BEFORE INSERT OR UPDATE ON feature_flags
  FOR EACH ROW EXECUTE FUNCTION trg_feature_flags_dependency();
-- =====================================================================
--  04 · Taxonomy (sections, categories, tags, eras) and people
--  Decisions: 4 (6 categories, one sub-level), 5 (7 sections), 6 (authors/guests)
-- =====================================================================

CREATE TABLE sections (
  id              smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  key             varchar(20) NOT NULL UNIQUE CHECK (key IN (
                    'podcast', 'success_stories', 'made_in_nablus', 'nablus_history',
                    'initiatives', 'round_table', 'awareness')),          -- stable key used by code
  name_ar         varchar(80) NOT NULL,
  slug            slug_text   NOT NULL UNIQUE,
  description     text,
  cover_media_id  bigint   REFERENCES media_assets (id) ON DELETE SET NULL,
  seo_meta_id     bigint   UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  sort_order      integer  NOT NULL DEFAULT 0,
  is_visible      boolean  NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE categories (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  parent_id       integer REFERENCES categories (id) ON DELETE RESTRICT,
  name_ar         varchar(80) NOT NULL,
  slug            slug_text   NOT NULL UNIQUE,
  description     text,
  is_highlighted  boolean NOT NULL DEFAULT false,    -- «محلي (نابلس)» shown as a featured menu item
  seo_meta_id     bigint  UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  sort_order      integer NOT NULL DEFAULT 0,
  is_active       boolean NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  CHECK (parent_id IS DISTINCT FROM id),
  UNIQUE (parent_id, name_ar)
);
CREATE INDEX categories_parent_idx ON categories (parent_id);

-- 4.2: exactly one level of sub-categories.
CREATE FUNCTION trg_categories_one_level() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.parent_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM categories WHERE id = NEW.parent_id AND parent_id IS NOT NULL) THEN
      RAISE EXCEPTION 'Sub-categories cannot have children (one level only)'
        USING ERRCODE = 'check_violation';
    END IF;
    IF TG_OP = 'UPDATE' AND EXISTS (SELECT 1 FROM categories WHERE parent_id = NEW.id) THEN
      RAISE EXCEPTION 'A category with sub-categories cannot become a sub-category'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER categories_one_level
  BEFORE INSERT OR UPDATE OF parent_id ON categories
  FOR EACH ROW EXECUTE FUNCTION trg_categories_one_level();

CREATE TABLE tags (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name_ar      varchar(80) NOT NULL UNIQUE,
  slug         slug_text   NOT NULL UNIQUE,
  seo_meta_id  bigint UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  search_name  text GENERATED ALWAYS AS (normalize_ar(name_ar)) STORED,
  created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX tags_search_trgm ON tags USING gin (search_name gin_trgm_ops);

-- Eras of Nablus economic history (5.4) — admin-managed list instead of free text.
CREATE TABLE eras (
  id          smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name_ar     varchar(80) NOT NULL UNIQUE,
  year_from   smallint,
  year_to     smallint,
  sort_order  integer NOT NULL DEFAULT 0,
  CHECK (year_to IS NULL OR year_from IS NULL OR year_to >= year_from)
);

-- ---------------------------------------------------------------------
--  People (decision 6)
-- ---------------------------------------------------------------------

CREATE TABLE authors (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name            varchar(120) NOT NULL,
  slug            slug_text    NOT NULL UNIQUE,
  job_title       varchar(120),
  bio             text,
  photo_media_id  bigint REFERENCES media_assets (id) ON DELETE SET NULL,
  user_id         bigint UNIQUE REFERENCES users (id) ON DELETE SET NULL,   -- 6.6 future writer account
  is_active       boolean NOT NULL DEFAULT true,
  team_sort_order smallint CHECK (team_sort_order >= 0),   -- NULL = not on the «فريق العمل» page (28)
  seo_meta_id     bigint  UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  search_name     text GENERATED ALWAYS AS (normalize_ar(name)) STORED,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  deleted_at      timestamptz
);
COMMENT ON TABLE authors IS 'Raqam people: bylines and team page. A post with no author row is shown as «فريق رَقَم» (6.5).';
CREATE INDEX authors_team_idx ON authors (team_sort_order) WHERE team_sort_order IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX authors_search_trgm ON authors USING gin (search_name gin_trgm_ops);

CREATE TABLE author_links (
  author_id      bigint      NOT NULL REFERENCES authors (id) ON DELETE CASCADE,
  platform_code  varchar(16) NOT NULL REFERENCES social_platforms (code) ON DELETE RESTRICT,
  url            url_text    NOT NULL,
  PRIMARY KEY (author_id, platform_code)
);

CREATE TABLE guests (
  id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name             varchar(120) NOT NULL,
  slug             slug_text    NOT NULL UNIQUE,
  job_title        varchar(120),
  organization_id  bigint REFERENCES organizations (id) ON DELETE SET NULL,
  bio              text,
  photo_media_id   bigint REFERENCES media_assets (id) ON DELETE SET NULL,
  seo_meta_id      bigint UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  search_name      text GENERATED ALWAYS AS (normalize_ar(name)) STORED,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz
);
CREATE INDEX guests_organization_idx ON guests (organization_id);
CREATE INDEX guests_search_trgm ON guests USING gin (search_name gin_trgm_ops);

CREATE TABLE guest_links (
  guest_id       bigint      NOT NULL REFERENCES guests (id) ON DELETE CASCADE,
  platform_code  varchar(16) NOT NULL REFERENCES social_platforms (code) ON DELETE RESTRICT,
  url            url_text    NOT NULL,
  PRIMARY KEY (guest_id, platform_code)
);

-- Role of a guest inside one item (6.10): host / guest / panelist
CREATE TABLE guest_roles (
  code     varchar(10) PRIMARY KEY CHECK (code ~ '^[a-z]+$'),
  name_ar  varchar(30) NOT NULL UNIQUE
);
-- =====================================================================
--  05 · Video (decision 8) and awareness characters (decision 7)
-- =====================================================================

-- Supertype: every video, whatever its source.
CREATE TABLE videos (
  id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source               varchar(8)  NOT NULL CHECK (source IN ('youtube', 'upload')),
  display_title        varchar(255),          -- admin override (8.4); required for uploads
  display_description  text,
  duration_seconds     integer CHECK (duration_seconds > 0),
  upload_media_id      bigint UNIQUE REFERENCES media_assets (id) ON DELETE RESTRICT,   -- 8.11 short clip
  poster_media_id      bigint REFERENCES media_assets (id) ON DELETE SET NULL,
  created_by           bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  deleted_at           timestamptz,
  UNIQUE (id, source),                                    -- target of the subtype FK below
  CHECK ((source = 'upload') = (upload_media_id IS NOT NULL)),
  CHECK (source = 'youtube' OR display_title IS NOT NULL)
);

-- Subtype: YouTube-specific facts (only for source = 'youtube').
-- The composite FK (video_id, source) guarantees a YouTube row can never
-- hang off an uploaded video ("subtype integrity").
CREATE TABLE youtube_videos (
  video_id                 bigint      PRIMARY KEY,
  source                   varchar(8)  NOT NULL DEFAULT 'youtube' CHECK (source = 'youtube'),
  youtube_id               varchar(11) NOT NULL UNIQUE CHECK (youtube_id ~ '^[A-Za-z0-9_-]{11}$'),
  is_short                 boolean     NOT NULL DEFAULT false,
  source_title             varchar(255) NOT NULL,       -- as fetched (8.3)
  source_description       text,
  thumbnail_url            url_text,
  published_on_youtube_at  timestamptz,
  availability             varchar(8)  NOT NULL DEFAULT 'ok'
                           CHECK (availability IN ('ok', 'private', 'removed', 'unknown')),   -- 8.12
  last_checked_at          timestamptz,
  fetched_at               timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (video_id, source) REFERENCES videos (id, source) ON DELETE CASCADE
);
CREATE INDEX youtube_videos_check_idx ON youtube_videos (last_checked_at NULLS FIRST);

CREATE TABLE video_chapters (                               -- 8.8 / 5.1 / 5.6
  video_id           bigint       NOT NULL REFERENCES videos (id) ON DELETE CASCADE,
  starts_at_seconds  integer      NOT NULL CHECK (starts_at_seconds >= 0),
  title              varchar(160) NOT NULL,
  PRIMARY KEY (video_id, starts_at_seconds)
);

CREATE TABLE playlists (                                     -- 8.9
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name_ar         varchar(120) NOT NULL,
  slug            slug_text    NOT NULL UNIQUE,
  description     text,
  section_id      smallint REFERENCES sections (id) ON DELETE SET NULL,
  cover_media_id  bigint   REFERENCES media_assets (id) ON DELETE SET NULL,
  seo_meta_id     bigint   UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  sort_order      integer  NOT NULL DEFAULT 0,
  is_visible      boolean  NOT NULL DEFAULT true,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX playlists_section_idx ON playlists (section_id);

CREATE TABLE playlist_videos (
  playlist_id  bigint  NOT NULL REFERENCES playlists (id) ON DELETE CASCADE,
  video_id     bigint  NOT NULL REFERENCES videos (id) ON DELETE CASCADE,
  sort_order   integer NOT NULL,
  PRIMARY KEY (playlist_id, video_id),
  -- Deferrable: drag-and-drop reordering can swap positions inside one transaction.
  CONSTRAINT playlist_videos_position_uq UNIQUE (playlist_id, sort_order) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX playlist_videos_video_idx ON playlist_videos (video_id);

-- ---------------------------------------------------------------------
--  Awareness characters (decision 7)
-- ---------------------------------------------------------------------

CREATE TABLE characters (
  id             smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name_ar        varchar(60)  NOT NULL UNIQUE,
  slug           slug_text    NOT NULL UNIQUE,
  role_ar        varchar(200) NOT NULL,
  description    text,
  accent_color   hex_color    NOT NULL,
  rive_media_id  bigint REFERENCES media_assets (id) ON DELETE SET NULL,   -- 7.10 animation file
  seo_meta_id    bigint UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  sort_order     integer NOT NULL DEFAULT 0,
  is_active      boolean NOT NULL DEFAULT true,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE pose_types (                                    -- 7.9
  code        varchar(12) PRIMARY KEY CHECK (code ~ '^[a-z]+$'),
  name_ar     varchar(30) NOT NULL UNIQUE,
  sort_order  integer     NOT NULL DEFAULT 0
);

CREATE TABLE character_poses (
  id               integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  character_id     smallint    NOT NULL REFERENCES characters (id) ON DELETE CASCADE,
  pose_type_code   varchar(12) NOT NULL REFERENCES pose_types (code) ON DELETE RESTRICT,
  static_media_id  bigint      NOT NULL REFERENCES media_assets (id) ON DELETE RESTRICT,  -- fallback image
  rive_state       varchar(60),
  UNIQUE (character_id, pose_type_code)
);

CREATE TABLE awareness_types (
  code        varchar(16) PRIMARY KEY CHECK (code ~ '^[a-z_]+$'),
  name_ar     varchar(40) NOT NULL UNIQUE,
  sort_order  integer     NOT NULL DEFAULT 0
);
-- =====================================================================
--  06 · Content (decisions 3, 5, 28)
--  Supertype `posts` + one subtype table per kind that has its own facts
--  ("class table inheritance"). This replaces a JSONB `extra` bag (1NF)
--  and lets a new kind be added by adding a table, never by altering posts.
-- =====================================================================

-- The 11 kinds. A kind's section is a fact about the kind, not the post:
-- storing section_id on posts would be a transitive dependency (post -> kind -> section).
CREATE TABLE post_kinds (
  code               varchar(12) PRIMARY KEY CHECK (code ~ '^[a-z]+$'),
  name_ar            varchar(40) NOT NULL UNIQUE,
  section_id         smallint REFERENCES sections (id) ON DELETE RESTRICT,   -- NULL = general news kinds
  requires_category  boolean     NOT NULL,
  schema_org_type    varchar(32) NOT NULL,                                   -- JSON-LD (23.9)
  sort_order         integer     NOT NULL DEFAULT 0,
  CHECK (section_id IS NOT NULL OR requires_category)
);

CREATE TABLE posts (
  id                       bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,   -- appears in URLs (23.2)
  kind_code                varchar(12)  NOT NULL REFERENCES post_kinds (code) ON DELETE RESTRICT,
  category_id              integer      REFERENCES categories (id) ON DELETE RESTRICT,
  title                    varchar(255) NOT NULL,
  subtitle                 varchar(255),
  slug                     slug_text    NOT NULL,      -- not unique: the id is authoritative, old slugs 301
  excerpt                  varchar(500),
  body                     text         NOT NULL DEFAULT '',   -- sanitised HTML
  cover_media_id           bigint REFERENCES media_assets (id) ON DELETE RESTRICT,
  primary_video_id         bigint REFERENCES videos (id) ON DELETE SET NULL,
  status                   varchar(10)  NOT NULL DEFAULT 'draft'
                           CHECK (status IN ('draft', 'scheduled', 'published', 'archived')),
  published_at             timestamptz,
  is_featured              boolean      NOT NULL DEFAULT false,
  breaking_until           timestamptz,                 -- breaking = breaking_until > now()
  sponsor_organization_id  bigint REFERENCES organizations (id) ON DELETE RESTRICT,  -- sponsored = NOT NULL
  correction_note          text,                        -- corrections policy (28)
  corrected_at             timestamptz,
  seo_meta_id              bigint UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  -- Derived search key for the PostgreSQL fallback search (10.11); maintained by the DB.
  search_text              text GENERATED ALWAYS AS (normalize_ar(
                             title || ' ' || COALESCE(subtitle, '') || ' ' || COALESCE(excerpt, ''))) STORED,
  created_by               bigint REFERENCES users (id) ON DELETE SET NULL,
  updated_by               bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at               timestamptz NOT NULL DEFAULT now(),
  updated_at               timestamptz NOT NULL DEFAULT now(),
  deleted_at               timestamptz,                 -- trash, purged after 90 days
  UNIQUE (id, kind_code),                               -- target for subtype FKs
  CHECK (status = 'draft' OR published_at IS NOT NULL),
  CHECK (status = 'draft' OR cover_media_id IS NOT NULL),          -- main image required (3)
  CHECK (status = 'draft' OR length(btrim(body)) > 0),             -- text required (3)
  CHECK ((correction_note IS NULL) = (corrected_at IS NULL)),
  CHECK (breaking_until IS NULL OR published_at IS NULL OR breaking_until > published_at)
);
COMMENT ON COLUMN posts.breaking_until IS 'Replaces is_breaking: a post is breaking while now() < breaking_until.';
COMMENT ON COLUMN posts.sponsor_organization_id IS 'Replaces is_sponsored + sponsor_name: sponsored iff not null.';

-- Listing indexes cover only live published rows (partial indexes = small + fast).
CREATE INDEX posts_published_idx ON posts (published_at DESC)
  WHERE status = 'published' AND deleted_at IS NULL;
CREATE INDEX posts_category_published_idx ON posts (category_id, published_at DESC)
  WHERE status = 'published' AND deleted_at IS NULL;
CREATE INDEX posts_kind_published_idx ON posts (kind_code, published_at DESC)
  WHERE status = 'published' AND deleted_at IS NULL;
CREATE INDEX posts_featured_idx ON posts (published_at DESC)
  WHERE is_featured AND status = 'published' AND deleted_at IS NULL;
CREATE INDEX posts_breaking_idx ON posts (breaking_until) WHERE breaking_until IS NOT NULL;
CREATE INDEX posts_scheduled_idx ON posts (published_at) WHERE status = 'scheduled';
CREATE INDEX posts_trash_idx ON posts (deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX posts_search_trgm ON posts USING gin (search_text gin_trgm_ops)   -- fallback search
  WHERE status = 'published' AND deleted_at IS NULL;
CREATE INDEX posts_cover_idx ON posts (cover_media_id);
CREATE INDEX posts_video_idx ON posts (primary_video_id);
CREATE INDEX posts_sponsor_idx ON posts (sponsor_organization_id);

-- Kind rules that need another table (requires_category) and kind immutability.
CREATE FUNCTION trg_posts_kind_rules() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_requires boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.kind_code <> OLD.kind_code THEN
    RAISE EXCEPTION 'The kind of a post cannot change after creation' USING ERRCODE = 'check_violation';
  END IF;
  SELECT requires_category INTO v_requires FROM post_kinds WHERE code = NEW.kind_code;
  IF v_requires AND NEW.status <> 'draft' AND NEW.category_id IS NULL THEN
    RAISE EXCEPTION 'Kind "%" needs a category before it can leave draft', NEW.kind_code
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER posts_kind_rules
  BEFORE INSERT OR UPDATE OF kind_code, category_id, status ON posts
  FOR EACH ROW EXECUTE FUNCTION trg_posts_kind_rules();

-- ---------------------------------------------------------------------
--  Post relations (many-to-many)
-- ---------------------------------------------------------------------

CREATE TABLE post_authors (                               -- 6.3 several authors, ordered
  post_id     bigint   NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  author_id   bigint   NOT NULL REFERENCES authors (id) ON DELETE RESTRICT,
  sort_order  smallint NOT NULL DEFAULT 0,
  PRIMARY KEY (post_id, author_id)
);
CREATE INDEX post_authors_author_idx ON post_authors (author_id);

CREATE TABLE post_tags (
  post_id  bigint NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  tag_id   bigint NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
  PRIMARY KEY (post_id, tag_id)
);
CREATE INDEX post_tags_tag_idx ON post_tags (tag_id);

CREATE TABLE post_guests (                                -- 6.9 / 6.10
  post_id     bigint      NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  guest_id    bigint      NOT NULL REFERENCES guests (id) ON DELETE RESTRICT,
  role_code   varchar(10) NOT NULL REFERENCES guest_roles (code) ON DELETE RESTRICT,
  sort_order  smallint    NOT NULL DEFAULT 0,
  PRIMARY KEY (post_id, guest_id)
);
CREATE INDEX post_guests_guest_idx ON post_guests (guest_id);

CREATE TABLE post_related (                               -- «اقرأ أيضاً» / 7.12
  post_id          bigint   NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  related_post_id  bigint   NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  sort_order       smallint NOT NULL DEFAULT 0,
  PRIMARY KEY (post_id, related_post_id),
  CHECK (post_id <> related_post_id)
);
CREATE INDEX post_related_related_idx ON post_related (related_post_id);

CREATE TABLE post_gallery_items (                         -- 9.6
  post_id     bigint   NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  media_id    bigint   NOT NULL REFERENCES media_assets (id) ON DELETE RESTRICT,
  sort_order  smallint NOT NULL DEFAULT 0,
  PRIMARY KEY (post_id, media_id)
);
CREATE INDEX post_gallery_media_idx ON post_gallery_items (media_id);

-- Media and videos used INSIDE the body HTML. The app rewrites these rows each
-- time the body is saved, so the database knows every usage:
--   * an image used in an article body cannot be deleted (RESTRICT)
--   * when a YouTube video turns private/removed (8.12) we can list every post using it
CREATE TABLE post_body_media (
  post_id   bigint NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  media_id  bigint NOT NULL REFERENCES media_assets (id) ON DELETE RESTRICT,
  PRIMARY KEY (post_id, media_id)
);
CREATE INDEX post_body_media_media_idx ON post_body_media (media_id);

CREATE TABLE post_body_videos (
  post_id   bigint NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  video_id  bigint NOT NULL REFERENCES videos (id) ON DELETE RESTRICT,
  PRIMARY KEY (post_id, video_id)
);
CREATE INDEX post_body_videos_video_idx ON post_body_videos (video_id);

-- Every place a video is used (main video or inside the body).
CREATE VIEW video_usage AS
SELECT primary_video_id AS video_id, id AS post_id, 'primary'::text AS usage
FROM posts WHERE primary_video_id IS NOT NULL AND deleted_at IS NULL
UNION ALL
SELECT bv.video_id, bv.post_id, 'body' FROM post_body_videos bv
JOIN posts p ON p.id = bv.post_id AND p.deleted_at IS NULL;

-- Revision history (3): a snapshot of the versioned text fields.
CREATE TABLE post_revisions (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  post_id      bigint  NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  revision_no  integer NOT NULL CHECK (revision_no > 0),
  title        varchar(255) NOT NULL,
  subtitle     varchar(255),
  excerpt      varchar(500),
  body         text NOT NULL,
  created_by   bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (post_id, revision_no)
);

-- ---------------------------------------------------------------------
--  Subtypes (one row per post of that kind, same primary key)
--  Pattern: (post_id, kind_code) -> posts(id, kind_code), kind fixed by CHECK.
-- ---------------------------------------------------------------------

CREATE TABLE podcast_seasons (
  id             smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  season_number  smallint NOT NULL UNIQUE CHECK (season_number > 0),
  title_ar       varchar(120),
  playlist_id    bigint UNIQUE REFERENCES playlists (id) ON DELETE SET NULL   -- 5.1 season = playlist
);

CREATE TABLE podcast_episodes (                           -- 5.1
  post_id         bigint      PRIMARY KEY,
  kind_code       varchar(12) NOT NULL DEFAULT 'episode' CHECK (kind_code = 'episode'),
  season_id       smallint    NOT NULL REFERENCES podcast_seasons (id) ON DELETE RESTRICT,
  episode_number  smallint    NOT NULL CHECK (episode_number > 0),
  FOREIGN KEY (post_id, kind_code) REFERENCES posts (id, kind_code) ON DELETE CASCADE,
  UNIQUE (season_id, episode_number)
);

CREATE TABLE success_stories (                            -- 5.2 (sector/city/year come from the organization)
  post_id          bigint      PRIMARY KEY,
  kind_code        varchar(12) NOT NULL DEFAULT 'story' CHECK (kind_code = 'story'),
  organization_id  bigint      NOT NULL REFERENCES organizations (id) ON DELETE RESTRICT,
  person_name      varchar(120),
  FOREIGN KEY (post_id, kind_code) REFERENCES posts (id, kind_code) ON DELETE CASCADE
);
CREATE INDEX success_stories_org_idx ON success_stories (organization_id);

CREATE TABLE success_story_figures (                      -- «أرقام بارزة» as rows, not an array
  post_id     bigint      NOT NULL REFERENCES success_stories (post_id) ON DELETE CASCADE,
  sort_order  smallint    NOT NULL,
  value       varchar(40) NOT NULL,        -- e.g. "120"
  label       varchar(120) NOT NULL,       -- e.g. "موظفاً"
  PRIMARY KEY (post_id, sort_order)
);

CREATE TABLE products (                                   -- 5.3 Made in Nablus
  post_id          bigint       PRIMARY KEY,
  kind_code        varchar(12)  NOT NULL DEFAULT 'product' CHECK (kind_code = 'product'),
  product_name     varchar(160) NOT NULL,
  organization_id  bigint       NOT NULL REFERENCES organizations (id) ON DELETE RESTRICT,
  contact_url      url_text,
  contact_phone    phone_e164,
  FOREIGN KEY (post_id, kind_code) REFERENCES posts (id, kind_code) ON DELETE CASCADE
);
CREATE INDEX products_org_idx ON products (organization_id);

CREATE TABLE history_entries (                            -- 5.4 timeline
  post_id       bigint      PRIMARY KEY,
  kind_code     varchar(12) NOT NULL DEFAULT 'history' CHECK (kind_code = 'history'),
  era_id        smallint    NOT NULL REFERENCES eras (id) ON DELETE RESTRICT,
  period_label  varchar(80),
  year_from     smallint,
  year_to       smallint,
  FOREIGN KEY (post_id, kind_code) REFERENCES posts (id, kind_code) ON DELETE CASCADE,
  CHECK (year_to IS NULL OR year_from IS NULL OR year_to >= year_from)
);
CREATE INDEX history_entries_timeline_idx ON history_entries (era_id, year_from);

CREATE TABLE initiatives (                                -- 5.5
  post_id                    bigint       PRIMARY KEY,
  kind_code                  varchar(12)  NOT NULL DEFAULT 'initiative' CHECK (kind_code = 'initiative'),
  initiative_name            varchar(160) NOT NULL,
  organizer_organization_id  bigint       NOT NULL REFERENCES organizations (id) ON DELETE RESTRICT,
  status                     varchar(8)   NOT NULL DEFAULT 'ongoing' CHECK (status IN ('ongoing', 'ended')),
  url                        url_text,
  FOREIGN KEY (post_id, kind_code) REFERENCES posts (id, kind_code) ON DELETE CASCADE
);
CREATE INDEX initiatives_status_idx ON initiatives (status);
CREATE INDEX initiatives_org_idx ON initiatives (organizer_organization_id);

CREATE TABLE roundtable_sessions (                        -- 5.6 (title = post title, participants = post_guests)
  post_id    bigint      PRIMARY KEY,
  kind_code  varchar(12) NOT NULL DEFAULT 'roundtable' CHECK (kind_code = 'roundtable'),
  held_on    date        NOT NULL,
  FOREIGN KEY (post_id, kind_code) REFERENCES posts (id, kind_code) ON DELETE CASCADE
);

CREATE TABLE awareness_cards (                            -- 5.7 / 7.11 (character comes from the pose)
  post_id              bigint      PRIMARY KEY,
  kind_code            varchar(12) NOT NULL DEFAULT 'awareness' CHECK (kind_code = 'awareness'),
  character_pose_id    integer     NOT NULL REFERENCES character_poses (id) ON DELETE RESTRICT,
  awareness_type_code  varchar(16) NOT NULL REFERENCES awareness_types (code) ON DELETE RESTRICT,
  FOREIGN KEY (post_id, kind_code) REFERENCES posts (id, kind_code) ON DELETE CASCADE
);
CREATE INDEX awareness_cards_pose_idx ON awareness_cards (character_pose_id);

CREATE TABLE infographics (                               -- 9.11 full-size download
  post_id            bigint      PRIMARY KEY,
  kind_code          varchar(12) NOT NULL DEFAULT 'infographic' CHECK (kind_code = 'infographic'),
  download_media_id  bigint      NOT NULL REFERENCES media_assets (id) ON DELETE RESTRICT,
  FOREIGN KEY (post_id, kind_code) REFERENCES posts (id, kind_code) ON DELETE CASCADE
);

-- A section post (and an infographic) must have its subtype row before it leaves draft.
-- DEFERRED constraint trigger: checked at COMMIT, so the post and its
-- subtype row can be inserted in either order inside one transaction.
CREATE FUNCTION trg_posts_subtype_present() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_table text := CASE NEW.kind_code
    WHEN 'episode'    THEN 'podcast_episodes'
    WHEN 'story'      THEN 'success_stories'
    WHEN 'product'    THEN 'products'
    WHEN 'history'    THEN 'history_entries'
    WHEN 'initiative' THEN 'initiatives'
    WHEN 'roundtable' THEN 'roundtable_sessions'
    WHEN 'awareness'  THEN 'awareness_cards'
    WHEN 'infographic' THEN 'infographics'          -- the downloadable file (9.11)
    ELSE NULL END;
  v_found boolean;
BEGIN
  IF v_table IS NULL OR NEW.status = 'draft' OR NEW.deleted_at IS NOT NULL THEN
    RETURN NULL;
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE post_id = $1)', v_table)
    INTO v_found USING NEW.id;
  IF NOT v_found THEN
    RAISE EXCEPTION 'Post % (kind %) needs its % row before leaving draft', NEW.id, NEW.kind_code, v_table
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER posts_subtype_present
  AFTER INSERT OR UPDATE ON posts
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION trg_posts_subtype_present();

-- ---------------------------------------------------------------------
--  Static pages (28)
-- ---------------------------------------------------------------------
CREATE TABLE pages (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  system_key   varchar(24) UNIQUE CHECK (system_key ~ '^[a-z_]+$'),   -- about, privacy, ... (code links)
  title        varchar(160) NOT NULL,
  slug         slug_text    NOT NULL UNIQUE,
  body         text         NOT NULL DEFAULT '',
  is_published boolean      NOT NULL DEFAULT false,
  seo_meta_id  bigint UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  updated_by   bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);
-- =====================================================================
--  07 · Currency board (decision 11) and weather (decision 12)
-- =====================================================================

-- Which currencies appear on the board, and their buy/sell spread (11.1, 11.4).
CREATE TABLE rate_board_currencies (
  currency_code     char(3)      PRIMARY KEY REFERENCES currencies (code) ON DELETE RESTRICT,
  buy_spread_bp     basis_points NOT NULL DEFAULT 50,
  sell_spread_bp    basis_points NOT NULL DEFAULT 50,
  display_decimals  smallint     NOT NULL DEFAULT 3 CHECK (display_decimals BETWEEN 0 AND 6),
  sort_order        integer      NOT NULL DEFAULT 0,
  is_active         boolean      NOT NULL DEFAULT true,
  updated_at        timestamptz  NOT NULL DEFAULT now(),
  CHECK (currency_code <> 'ILS')                       -- ILS is the quote currency
);

-- Official representative rates from the Bank of Israel (decision 11, revised 2026-10-12):
-- ILS per 1 unit of currency_code, one publication per business day.
-- effective_at = the provider's own publication time (lastUpdate), so the table
-- also works unchanged if an intraday provider is used later.
-- All rows are kept forever (11.13); with daily data there is nothing to prune,
-- so no separate "daily close" table is needed (it would duplicate this one).
CREATE TABLE exchange_rates (
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  currency_code  char(3)        NOT NULL REFERENCES currencies (code) ON DELETE RESTRICT,
  provider_code  varchar(32)    NOT NULL REFERENCES data_providers (code) ON DELETE RESTRICT,
  mid_rate       numeric(20,10) NOT NULL CHECK (mid_rate > 0),   -- already divided by the provider's "unit"
  effective_at   timestamptz    NOT NULL,
  fetched_at     timestamptz    NOT NULL DEFAULT now(),
  UNIQUE (currency_code, effective_at),
  CHECK (currency_code <> 'ILS'),
  CHECK (fetched_at >= effective_at - interval '1 day')
);
CREATE INDEX exchange_rates_latest_idx ON exchange_rates (currency_code, effective_at DESC);

-- Currencies with a fixed official peg are never fetched: their rate is derived
-- from the anchor (AED = 3.6725 per USD, SAR = 3.75 per USD). Storing their
-- rates would duplicate information already in exchange_rates.
CREATE TABLE currency_pegs (
  currency_code     char(3)        PRIMARY KEY REFERENCES currencies (code) ON DELETE RESTRICT,
  anchor_code       char(3)        NOT NULL REFERENCES currencies (code) ON DELETE RESTRICT,
  units_per_anchor  numeric(20,10) NOT NULL CHECK (units_per_anchor > 0),
  CHECK (currency_code <> anchor_code),
  CHECK (currency_code <> 'ILS' AND anchor_code <> 'ILS')
);

-- A pegged currency must not receive fetched rows (single source of truth).
CREATE FUNCTION trg_exchange_rates_not_pegged() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM currency_pegs WHERE currency_code = NEW.currency_code) THEN
    RAISE EXCEPTION '% is pegged; its rate is derived from its anchor currency', NEW.currency_code
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER exchange_rates_not_pegged
  BEFORE INSERT OR UPDATE OF currency_code ON exchange_rates
  FOR EACH ROW EXECUTE FUNCTION trg_exchange_rates_not_pegged();

-- Fetched rates + derived pegged rates, in one shape.
CREATE VIEW effective_exchange_rates AS
SELECT e.currency_code, e.mid_rate, e.effective_at, e.provider_code, false AS is_pegged
FROM exchange_rates e
UNION ALL
SELECT p.currency_code, round(e.mid_rate / p.units_per_anchor, 10), e.effective_at, e.provider_code, true
FROM currency_pegs p
JOIN exchange_rates e ON e.currency_code = p.anchor_code;

-- Manual buy/sell override, optionally time-limited (11.5).
-- EXCLUDE: two overrides for the same currency may never overlap in time.
CREATE TABLE rate_overrides (
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  currency_code  char(3)        NOT NULL REFERENCES rate_board_currencies (currency_code) ON DELETE CASCADE,
  buy_rate       numeric(20,10) NOT NULL CHECK (buy_rate > 0),
  sell_rate      numeric(20,10) NOT NULL CHECK (sell_rate > 0),
  valid_from     timestamptz    NOT NULL DEFAULT now(),
  valid_until    timestamptz,                    -- NULL = until removed
  created_by     bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at     timestamptz    NOT NULL DEFAULT now(),
  CHECK (sell_rate >= buy_rate),
  CHECK (valid_until IS NULL OR valid_until > valid_from),
  CONSTRAINT rate_overrides_no_overlap
    EXCLUDE USING gist (currency_code WITH =, tstzrange(valid_from, valid_until, '[)') WITH &&)
);

-- The board as shown on the site: latest official rate, spread or manual
-- override, and change versus the previous publication day. Nothing derived is stored.
CREATE VIEW rate_board AS
SELECT b.currency_code,
       c.name_ar,
       c.symbol,
       b.sort_order,
       b.display_decimals,
       r.mid_rate,
       r.effective_at,
       (r.effective_at AT TIME ZONE 'Asia/Hebron')::date                              AS rate_date,
       r.is_pegged,
       COALESCE(o.buy_rate,  round(r.mid_rate * (1 - b.buy_spread_bp  / 10000.0), 6)) AS buy_rate,
       COALESCE(o.sell_rate, round(r.mid_rate * (1 + b.sell_spread_bp / 10000.0), 6)) AS sell_rate,
       (o.id IS NOT NULL)                                                             AS is_manual,
       d.mid_rate                                                                     AS previous_rate,
       CASE WHEN d.mid_rate IS NULL OR r.mid_rate IS NULL THEN NULL
            ELSE round((r.mid_rate - d.mid_rate) / d.mid_rate * 100, 2) END            AS change_pct
FROM rate_board_currencies b
JOIN currencies c ON c.code = b.currency_code
LEFT JOIN LATERAL (
  SELECT e.mid_rate, e.effective_at, e.is_pegged FROM effective_exchange_rates e
  WHERE e.currency_code = b.currency_code
  ORDER BY e.effective_at DESC LIMIT 1) r ON true
LEFT JOIN LATERAL (
  SELECT ov.id, ov.buy_rate, ov.sell_rate FROM rate_overrides ov
  WHERE ov.currency_code = b.currency_code
    AND ov.valid_from <= now() AND (ov.valid_until IS NULL OR ov.valid_until > now())
  LIMIT 1) o ON true
LEFT JOIN LATERAL (
  SELECT e.mid_rate FROM effective_exchange_rates e
  WHERE e.currency_code = b.currency_code
    AND (e.effective_at AT TIME ZONE 'Asia/Hebron')::date < (r.effective_at AT TIME ZONE 'Asia/Hebron')::date
  ORDER BY e.effective_at DESC LIMIT 1) d ON true
WHERE b.is_active;

-- ---------------------------------------------------------------------
--  Weather (decision 12)
-- ---------------------------------------------------------------------

CREATE TABLE weather_locations (
  city_id     integer PRIMARY KEY REFERENCES cities (id) ON DELETE CASCADE,
  is_default  boolean NOT NULL DEFAULT false,
  sort_order  integer NOT NULL DEFAULT 0,
  is_active   boolean NOT NULL DEFAULT true
);
-- Only one default city (Nablus).
CREATE UNIQUE INDEX weather_locations_one_default_uq ON weather_locations ((true)) WHERE is_default;

-- Provider condition codes -> Arabic text + Raqam icon (12.6, 12.8)
CREATE TABLE weather_conditions (
  code            smallint    PRIMARY KEY,
  description_ar  varchar(80) NOT NULL,
  icon_key        varchar(32) NOT NULL
);

CREATE TABLE weather_observations (                      -- current conditions, hourly
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  city_id           integer      NOT NULL REFERENCES weather_locations (city_id) ON DELETE CASCADE,
  provider_code     varchar(32)  NOT NULL REFERENCES data_providers (code) ON DELETE RESTRICT,
  observed_at       timestamptz  NOT NULL,
  temperature_c     numeric(4,1) NOT NULL CHECK (temperature_c BETWEEN -60 AND 70),
  feels_like_c      numeric(4,1) CHECK (feels_like_c BETWEEN -80 AND 80),
  humidity_pct      smallint     CHECK (humidity_pct BETWEEN 0 AND 100),
  wind_kmh          numeric(5,1) CHECK (wind_kmh >= 0),
  wind_deg          smallint     CHECK (wind_deg BETWEEN 0 AND 360),
  condition_code    smallint     NOT NULL REFERENCES weather_conditions (code) ON DELETE RESTRICT,
  is_day            boolean      NOT NULL,
  fetched_at        timestamptz  NOT NULL DEFAULT now(),
  UNIQUE (city_id, observed_at)
);
CREATE INDEX weather_observations_latest_idx ON weather_observations (city_id, observed_at DESC);

CREATE TABLE weather_forecasts (                         -- 5-day forecast, latest fetch replaces rows
  city_id         integer      NOT NULL REFERENCES weather_locations (city_id) ON DELETE CASCADE,
  forecast_date   date         NOT NULL,
  temp_min_c      numeric(4,1) NOT NULL,
  temp_max_c      numeric(4,1) NOT NULL,
  condition_code  smallint     NOT NULL REFERENCES weather_conditions (code) ON DELETE RESTRICT,
  provider_code   varchar(32)  NOT NULL REFERENCES data_providers (code) ON DELETE RESTRICT,
  fetched_at      timestamptz  NOT NULL DEFAULT now(),
  PRIMARY KEY (city_id, forecast_date),
  CHECK (temp_max_c >= temp_min_c)
);
-- =====================================================================
--  08 · Ads (13), services & FAQ (14, 28), bookings (15 — dormant),
--       payments & invoices (16 — dormant), customer features (17 — dormant)
-- =====================================================================

-- ---------------------------------------------------------------------
--  Advertising (decision 13)
-- ---------------------------------------------------------------------

CREATE TABLE ad_placements (
  code                 varchar(20) PRIMARY KEY CHECK (code IN (
                         'header_leaderboard', 'sidebar_mpu', 'in_article',
                         'between_sections', 'popup', 'mobile_sticky')),
  name_ar              varchar(60) NOT NULL,
  desktop_width        smallint CHECK (desktop_width  > 0),
  desktop_height       smallint CHECK (desktop_height > 0),
  mobile_width         smallint CHECK (mobile_width   > 0),
  mobile_height        smallint CHECK (mobile_height  > 0),   -- reserved sizes => no layout shift (13.10)
  is_enabled           boolean  NOT NULL DEFAULT true,
  empty_behavior       varchar(5) NOT NULL DEFAULT 'house' CHECK (empty_behavior IN ('house', 'hide')),  -- 13.13
  frequency_cap_hours  smallint CHECK (frequency_cap_hours > 0),                                        -- 13.2
  lazy_load            boolean  NOT NULL DEFAULT true,                                                  -- 13.11
  CHECK (code = 'popup' OR frequency_cap_hours IS NULL)
);

CREATE TABLE advertisers (
  id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  organization_id  bigint NOT NULL UNIQUE REFERENCES organizations (id) ON DELETE RESTRICT,
  contact_name     varchar(120),
  contact_phone    phone_e164,
  contact_email    email_address,
  notes            text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE ad_campaigns (
  id                     bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  advertiser_id          bigint       NOT NULL REFERENCES advertisers (id) ON DELETE RESTRICT,
  name                   varchar(160) NOT NULL,
  target_url             url_text     NOT NULL,
  starts_at              timestamptz  NOT NULL,
  ends_at                timestamptz  NOT NULL,
  priority               smallint     NOT NULL DEFAULT 50 CHECK (priority BETWEEN 1 AND 100),  -- 13.5
  status                 varchar(6)   NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'paused')),
  ending_alert_sent_at   timestamptz,                                                           -- 13.9
  created_by             bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at             timestamptz  NOT NULL DEFAULT now(),
  updated_at             timestamptz  NOT NULL DEFAULT now(),
  CHECK (ends_at > starts_at)
);
COMMENT ON COLUMN ad_campaigns.status IS '"ended" is not stored: a campaign has ended when now() >= ends_at (13.4).';
CREATE INDEX ad_campaigns_live_idx ON ad_campaigns (starts_at, ends_at) WHERE status = 'active';
CREATE INDEX ad_campaigns_advertiser_idx ON ad_campaigns (advertiser_id);

CREATE TABLE ad_creatives (                               -- 13.3 one image per device
  campaign_id  bigint     NOT NULL REFERENCES ad_campaigns (id) ON DELETE CASCADE,
  device       varchar(7) NOT NULL CHECK (device IN ('desktop', 'mobile')),
  media_id     bigint     NOT NULL REFERENCES media_assets (id) ON DELETE RESTRICT,
  PRIMARY KEY (campaign_id, device)
);

CREATE TABLE ad_campaign_placements (
  campaign_id     bigint      NOT NULL REFERENCES ad_campaigns (id) ON DELETE CASCADE,
  placement_code  varchar(20) NOT NULL REFERENCES ad_placements (code) ON DELETE RESTRICT,
  PRIMARY KEY (campaign_id, placement_code)
);
CREATE INDEX ad_campaign_placements_placement_idx ON ad_campaign_placements (placement_code);

CREATE TABLE ad_stats_daily (                             -- 13.6 – 13.8
  campaign_id     bigint      NOT NULL REFERENCES ad_campaigns (id) ON DELETE CASCADE,
  placement_code  varchar(20) NOT NULL REFERENCES ad_placements (code) ON DELETE RESTRICT,
  stat_date       date        NOT NULL,
  impressions     bigint      NOT NULL DEFAULT 0 CHECK (impressions >= 0),
  clicks          bigint      NOT NULL DEFAULT 0 CHECK (clicks >= 0),
  PRIMARY KEY (campaign_id, placement_code, stat_date)
);

-- «أعلن معنا» banner shown in an empty slot when empty_behavior = 'house' (13.13)
CREATE TABLE house_ads (
  placement_code    varchar(20)  PRIMARY KEY REFERENCES ad_placements (code) ON DELETE CASCADE,
  desktop_media_id  bigint REFERENCES media_assets (id) ON DELETE RESTRICT,
  mobile_media_id   bigint REFERENCES media_assets (id) ON DELETE RESTRICT,
  target_path       varchar(500) NOT NULL DEFAULT '/advertise' CHECK (target_path ~ '^(/|https?://)'),
  is_active         boolean      NOT NULL DEFAULT true,
  updated_at        timestamptz  NOT NULL DEFAULT now(),
  CHECK (desktop_media_id IS NOT NULL OR mobile_media_id IS NOT NULL)
);

CREATE VIEW live_ad_campaigns AS
SELECT c.*, p.placement_code
FROM ad_campaigns c
JOIN ad_campaign_placements p ON p.campaign_id = c.id
JOIN ad_placements pl ON pl.code = p.placement_code AND pl.is_enabled
WHERE c.status = 'active' AND c.starts_at <= now() AND c.ends_at > now();

-- ---------------------------------------------------------------------
--  Services, pricing and FAQ (decisions 14, 28)
-- ---------------------------------------------------------------------

CREATE TABLE service_groups (                             -- «تغطيات إعلامية» / «إعلانات»
  id          smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name_ar     varchar(80) NOT NULL UNIQUE,
  sort_order  integer     NOT NULL DEFAULT 0
);

CREATE TABLE services (
  id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  group_id           smallint     NOT NULL REFERENCES service_groups (id) ON DELETE RESTRICT,
  section_id         smallint     REFERENCES sections (id) ON DELETE SET NULL,   -- examples of past work (14.7)
  name_ar            varchar(120) NOT NULL,
  slug               slug_text    NOT NULL UNIQUE,
  summary            varchar(300) NOT NULL,
  description        text,
  cover_media_id     bigint REFERENCES media_assets (id) ON DELETE SET NULL,
  price_mode         varchar(10)  NOT NULL CHECK (price_mode IN ('fixed', 'from', 'on_request')),  -- 14.3
  price_amount       money_minor,
  currency_code      char(3)      REFERENCES currencies (code) ON DELETE RESTRICT,
  price_note         varchar(80),                                                   -- «للحلقة»
  sale_price_amount  money_minor,                                                   -- 14.4
  sale_ends_at       timestamptz,
  seo_meta_id        bigint  UNIQUE REFERENCES seo_meta (id) ON DELETE SET NULL,
  sort_order         integer NOT NULL DEFAULT 0,
  is_active          boolean NOT NULL DEFAULT true,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  CHECK ((price_mode = 'on_request') = (price_amount IS NULL)),
  CHECK ((price_amount IS NULL) = (currency_code IS NULL)),
  CHECK ((sale_price_amount IS NULL) = (sale_ends_at IS NULL)),
  CHECK (sale_price_amount IS NULL OR (price_mode <> 'on_request' AND sale_price_amount < price_amount))  -- an offer undercuts a stated price
);
CREATE INDEX services_group_idx ON services (group_id, sort_order) WHERE deleted_at IS NULL;

CREATE TABLE service_deliverables (                       -- «ماذا تشمل الخدمة»
  service_id  integer      NOT NULL REFERENCES services (id) ON DELETE CASCADE,
  sort_order  smallint     NOT NULL,
  label       varchar(200) NOT NULL,
  PRIMARY KEY (service_id, sort_order)
);

-- General FAQ page (service_id NULL) and per-service FAQ (14.7). Also feeds the chatbot (18.4).
CREATE TABLE faqs (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  service_id    integer REFERENCES services (id) ON DELETE CASCADE,
  question      varchar(300) NOT NULL,
  answer        text         NOT NULL,
  sort_order    integer      NOT NULL DEFAULT 0,
  is_published  boolean      NOT NULL DEFAULT true,
  created_at    timestamptz  NOT NULL DEFAULT now(),
  updated_at    timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX faqs_service_idx ON faqs (service_id, sort_order);

-- ---------------------------------------------------------------------
--  Bookings (decision 15 — built, switched off)
-- ---------------------------------------------------------------------

-- Booking contact, stored once per e-mail (no repetition per booking). A booking always
-- comes with a phone (checked by the application); it is emptied only when the person
-- deletes their account and the contact is made anonymous (17.7).
CREATE TABLE customers (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name          varchar(120)  NOT NULL,
  email         email_address NOT NULL UNIQUE,
  phone         phone_e164,
  company_name  varchar(160),
  created_at    timestamptz   NOT NULL DEFAULT now(),
  updated_at    timestamptz   NOT NULL DEFAULT now()
);

CREATE TABLE booking_statuses (                           -- workflow metadata (15.7, 15.11, 15.12)
  code                    varchar(16) PRIMARY KEY CHECK (code ~ '^[a-z_]+$'),
  name_ar                 varchar(40) NOT NULL UNIQUE,
  sort_order              integer     NOT NULL DEFAULT 0,
  is_terminal             boolean     NOT NULL DEFAULT false,
  notify_customer         boolean     NOT NULL DEFAULT true,
  requires_payment_flag   boolean     NOT NULL DEFAULT false
);

CREATE TABLE booking_status_transitions (                 -- allowed moves; extendable without code
  from_code  varchar(16) NOT NULL REFERENCES booking_statuses (code) ON DELETE CASCADE,
  to_code    varchar(16) NOT NULL REFERENCES booking_statuses (code) ON DELETE CASCADE,
  PRIMARY KEY (from_code, to_code),
  CHECK (from_code <> to_code)
);

CREATE TABLE bookings (
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  reference_year     smallint     NOT NULL,
  reference_seq      integer      NOT NULL CHECK (reference_seq > 0),
  reference          varchar(16)  GENERATED ALWAYS AS
                       ('RQ-' || reference_year::text || '-' || lpad(reference_seq::text, 5, '0')) STORED,   -- 15.4
  service_id         integer      NOT NULL REFERENCES services (id) ON DELETE RESTRICT,
  customer_id        bigint       NOT NULL REFERENCES customers (id) ON DELETE RESTRICT,
  user_id            bigint       REFERENCES users (id) ON DELETE SET NULL,      -- booked while logged in (dormant)
  preferred_contact  varchar(8)   NOT NULL CHECK (preferred_contact IN ('phone', 'whatsapp', 'email')),
  preferred_dates    varchar(500),
  details            text         NOT NULL,
  status_code        varchar(16)  NOT NULL DEFAULT 'new' REFERENCES booking_statuses (code) ON DELETE RESTRICT,
  price_amount       money_minor,                    -- snapshot of the price at submission (15.5)
  currency_code      char(3)      REFERENCES currencies (code) ON DELETE RESTRICT,
  access_token_hash  sha256_hex   NOT NULL UNIQUE,    -- 15.9 status link
  scheduled_for      timestamptz,
  published_post_id  bigint       REFERENCES posts (id) ON DELETE SET NULL,
  admin_notes        text,
  consent_at         timestamptz  NOT NULL,
  ip_hash            sha256_hex,
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  deleted_at         timestamptz,
  UNIQUE (reference_year, reference_seq),
  UNIQUE (reference),
  CHECK ((price_amount IS NULL) = (currency_code IS NULL))
);
CREATE INDEX bookings_status_idx   ON bookings (status_code, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX bookings_service_idx  ON bookings (service_id);
CREATE INDEX bookings_customer_idx ON bookings (customer_id);

CREATE TABLE booking_status_history (                     -- 15.8 (previous status = previous row)
  id                    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id            bigint       NOT NULL REFERENCES bookings (id) ON DELETE CASCADE,
  status_code           varchar(16)  NOT NULL REFERENCES booking_statuses (code) ON DELETE RESTRICT,
  note                  varchar(1000),
  changed_by            bigint REFERENCES users (id) ON DELETE SET NULL,
  customer_notified_at  timestamptz,
  created_at            timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX booking_status_history_booking_idx ON booking_status_history (booking_id, created_at);

CREATE TABLE booking_attachments (                        -- 15.2 up to 3 private files
  booking_id  bigint NOT NULL REFERENCES bookings (id) ON DELETE CASCADE,
  media_id    bigint NOT NULL REFERENCES media_assets (id) ON DELETE RESTRICT,
  PRIMARY KEY (booking_id, media_id)
);

-- At most 3 attachments per booking (15.2). The booking row is locked first, so two
-- concurrent uploads cannot both see 2 attachments and add a 4th.
CREATE FUNCTION trg_booking_attachments_limit() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  PERFORM 1 FROM bookings WHERE id = NEW.booking_id FOR UPDATE;
  IF (SELECT count(*) FROM booking_attachments
      WHERE booking_id = NEW.booking_id
        AND (TG_OP = 'INSERT' OR (booking_id, media_id) <> (OLD.booking_id, OLD.media_id))) >= 3 THEN
    RAISE EXCEPTION 'Booking % already has 3 attachments', NEW.booking_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER booking_attachments_limit
  BEFORE INSERT OR UPDATE OF booking_id ON booking_attachments
  FOR EACH ROW EXECUTE FUNCTION trg_booking_attachments_limit();

-- Ad space sold through a booking (dormant link)
ALTER TABLE ad_campaigns
  ADD COLUMN booking_id bigint REFERENCES bookings (id) ON DELETE SET NULL;

-- Booking reference numbers: RQ-<year>-<00001>, gap-free per year.
CREATE FUNCTION trg_bookings_reference() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.reference_year := local_year();
  NEW.reference_seq  := next_document_number('booking', NEW.reference_year);
  NEW.status_code    := 'new';
  RETURN NEW;
END $$;
CREATE TRIGGER bookings_reference
  BEFORE INSERT ON bookings
  FOR EACH ROW EXECUTE FUNCTION trg_bookings_reference();

-- First history row is written automatically.
CREATE FUNCTION trg_bookings_initial_history() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO booking_status_history (booking_id, status_code, note)
  VALUES (NEW.id, NEW.status_code, 'created');
  RETURN NULL;
END $$;
CREATE TRIGGER bookings_initial_history
  AFTER INSERT ON bookings
  FOR EACH ROW EXECUTE FUNCTION trg_bookings_initial_history();

-- Status changes happen ONLY by inserting a history row; the trigger validates
-- the move against booking_status_transitions and updates bookings.status_code.
CREATE FUNCTION trg_booking_history_apply() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_current varchar(16);
BEGIN
  SELECT status_code INTO v_current FROM bookings WHERE id = NEW.booking_id FOR UPDATE;
  IF NEW.status_code = v_current THEN
    RETURN NEW;                                   -- note only / initial row
  END IF;
  IF NOT EXISTS (SELECT 1 FROM booking_status_transitions
                 WHERE from_code = v_current AND to_code = NEW.status_code) THEN
    RAISE EXCEPTION 'Booking %: transition % -> % is not allowed', NEW.booking_id, v_current, NEW.status_code
      USING ERRCODE = 'check_violation';
  END IF;
  UPDATE bookings SET status_code = NEW.status_code WHERE id = NEW.booking_id;
  RETURN NEW;
END $$;
CREATE TRIGGER booking_history_apply
  BEFORE INSERT ON booking_status_history
  FOR EACH ROW EXECUTE FUNCTION trg_booking_history_apply();

-- Direct UPDATE of bookings.status_code is refused (keeps history complete).
CREATE FUNCTION trg_bookings_guard_status() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status_code IS DISTINCT FROM OLD.status_code AND pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'Change booking status by inserting into booking_status_history'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER bookings_guard_status
  BEFORE UPDATE OF status_code ON bookings
  FOR EACH ROW EXECUTE FUNCTION trg_bookings_guard_status();

-- ---------------------------------------------------------------------
--  Payments & invoices (decision 16 — built, switched off)
-- ---------------------------------------------------------------------

CREATE TABLE payment_gateways (
  code       varchar(32) PRIMARY KEY CHECK (code ~ '^[a-z0-9_]+$'),
  name_ar    varchar(60) NOT NULL,
  is_active  boolean     NOT NULL DEFAULT false
);

CREATE TABLE payments (                                   -- one row per attempt (16.4)
  id                      bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id              bigint      NOT NULL REFERENCES bookings (id) ON DELETE RESTRICT,
  gateway_code            varchar(32) NOT NULL REFERENCES payment_gateways (code) ON DELETE RESTRICT,
  attempt_no              smallint    NOT NULL CHECK (attempt_no > 0),
  gateway_order_id        varchar(64) NOT NULL UNIQUE,
  gateway_transaction_id  varchar(64),
  amount                  money_minor NOT NULL CHECK (amount > 0),
  currency_code           char(3)     NOT NULL REFERENCES currencies (code) ON DELETE RESTRICT,
  status                  varchar(20) NOT NULL DEFAULT 'pending' CHECK (status IN (
                            'pending', 'authorized', 'captured', 'failed',
                            'cancelled', 'refunded', 'partially_refunded')),
  idempotency_key         varchar(80) NOT NULL UNIQUE,          -- 16.8
  failure_reason          varchar(500),
  paid_at                 timestamptz,
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),
  UNIQUE (booking_id, attempt_no),
  UNIQUE (gateway_code, gateway_transaction_id),
  CHECK (status NOT IN ('captured', 'refunded', 'partially_refunded') OR paid_at IS NOT NULL),
  CHECK (status <> 'failed' OR failure_reason IS NOT NULL)
);
-- A booking can be successfully paid only once.
CREATE UNIQUE INDEX payments_one_success_per_booking_uq
  ON payments (booking_id) WHERE status IN ('authorized', 'captured');
CREATE INDEX payments_pending_idx ON payments (created_at) WHERE status = 'pending';   -- 16.7 reconciliation

-- Raw bank notifications. payload is an opaque archived document (never queried
-- field-by-field), so keeping it as jsonb does not break 1NF in practice.
CREATE TABLE payment_events (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  gateway_code      varchar(32)  NOT NULL REFERENCES payment_gateways (code) ON DELETE RESTRICT,
  gateway_event_id  varchar(100) NOT NULL,
  payment_id        bigint REFERENCES payments (id) ON DELETE SET NULL,
  event_type        varchar(60)  NOT NULL,
  signature_valid   boolean      NOT NULL,
  payload           jsonb        NOT NULL,
  received_at       timestamptz  NOT NULL DEFAULT now(),
  processed_at      timestamptz,
  UNIQUE (gateway_code, gateway_event_id)                          -- 16.6 processed once
);

CREATE TABLE invoices (                                   -- 16.9
  id                   bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  number_year          smallint     NOT NULL,
  number_seq           integer      NOT NULL CHECK (number_seq > 0),
  number               varchar(16)  GENERATED ALWAYS AS
                         ('INV-' || number_year::text || '-' || lpad(number_seq::text, 5, '0')) STORED,
  payment_id           bigint       NOT NULL UNIQUE REFERENCES payments (id) ON DELETE RESTRICT,   -- booking = payments.booking_id
  -- Legal snapshot at issue time (a historical fact, not a copy of customers.*)
  billed_name          varchar(120) NOT NULL,
  billed_email         email_address NOT NULL,
  billed_phone         phone_e164,
  billed_company       varchar(160),
  billed_tax_number    varchar(40),
  seller_tax_number    varchar(40),
  currency_code        char(3)      NOT NULL REFERENCES currencies (code) ON DELETE RESTRICT,
  tax_rate_bp          basis_points,                  -- NULL = no VAT (decision pending)
  issued_at            timestamptz  NOT NULL DEFAULT now(),
  pdf_media_id         bigint REFERENCES media_assets (id) ON DELETE RESTRICT,
  UNIQUE (number_year, number_seq),
  UNIQUE (number)
);

CREATE TABLE invoice_lines (
  invoice_id   bigint        NOT NULL REFERENCES invoices (id) ON DELETE RESTRICT,
  line_no      smallint      NOT NULL CHECK (line_no > 0),
  description  varchar(300)  NOT NULL,
  quantity     numeric(10,2) NOT NULL CHECK (quantity > 0),
  unit_amount  money_minor   NOT NULL,
  PRIMARY KEY (invoice_id, line_no)
);

-- Totals are computed, never stored (no update anomalies).
CREATE VIEW invoice_totals AS
SELECT i.id AS invoice_id,
       i.number,
       i.currency_code,
       s.subtotal,
       CASE WHEN i.tax_rate_bp IS NULL THEN 0
            ELSE round(s.subtotal * i.tax_rate_bp / 10000.0)::bigint END                    AS tax_amount,
       s.subtotal + CASE WHEN i.tax_rate_bp IS NULL THEN 0
            ELSE round(s.subtotal * i.tax_rate_bp / 10000.0)::bigint END                    AS total_amount
FROM invoices i
JOIN LATERAL (
  SELECT COALESCE(sum(round(l.quantity * l.unit_amount))::bigint, 0) AS subtotal
  FROM invoice_lines l WHERE l.invoice_id = i.id) s ON true;

CREATE FUNCTION trg_invoices_number() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.number_year := local_year();
  NEW.number_seq  := next_document_number('invoice', NEW.number_year);
  RETURN NEW;
END $$;
CREATE TRIGGER invoices_number
  BEFORE INSERT ON invoices
  FOR EACH ROW EXECUTE FUNCTION trg_invoices_number();

-- Issued invoices are immutable; only the PDF can be attached once.
CREATE FUNCTION trg_invoices_immutable() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION '% rows cannot be deleted', TG_TABLE_NAME USING ERRCODE = 'check_violation';
  END IF;
  IF TG_TABLE_NAME = 'invoice_lines' THEN
    RAISE EXCEPTION 'Invoice lines cannot be changed' USING ERRCODE = 'check_violation';
  END IF;
  -- invoices: allow exactly one change — attaching the PDF.
  IF OLD.pdf_media_id IS NOT NULL OR NEW.pdf_media_id IS NULL
     OR (NEW.payment_id, NEW.billed_name, NEW.billed_email, NEW.billed_phone,
         NEW.billed_company, NEW.billed_tax_number, NEW.seller_tax_number, NEW.currency_code,
         NEW.tax_rate_bp, NEW.issued_at, NEW.number_year, NEW.number_seq)
        IS DISTINCT FROM
        (OLD.payment_id, OLD.billed_name, OLD.billed_email, OLD.billed_phone,
         OLD.billed_company, OLD.billed_tax_number, OLD.seller_tax_number, OLD.currency_code,
         OLD.tax_rate_bp, OLD.issued_at, OLD.number_year, OLD.number_seq) THEN
    RAISE EXCEPTION 'Issued invoices are immutable (only the PDF can be attached once)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER invoices_immutable
  BEFORE UPDATE OR DELETE ON invoices
  FOR EACH ROW EXECUTE FUNCTION trg_invoices_immutable();
CREATE TRIGGER invoice_lines_immutable
  BEFORE UPDATE OR DELETE ON invoice_lines
  FOR EACH ROW EXECUTE FUNCTION trg_invoices_immutable();

CREATE TABLE refunds (                                    -- 16.10 (currency = payment currency)
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  payment_id         bigint      NOT NULL REFERENCES payments (id) ON DELETE RESTRICT,
  amount             money_minor NOT NULL CHECK (amount > 0),
  status             varchar(10) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'succeeded', 'failed')),
  gateway_refund_id  varchar(64),
  reason             varchar(500),
  created_by         bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (payment_id, gateway_refund_id)
);

-- Refunds can never exceed what was paid.
CREATE FUNCTION trg_refunds_not_exceed() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_paid     bigint;
  v_refunded bigint;
BEGIN
  SELECT amount INTO v_paid FROM payments WHERE id = NEW.payment_id FOR UPDATE;
  SELECT COALESCE(sum(amount), 0) INTO v_refunded
  FROM refunds WHERE payment_id = NEW.payment_id AND status <> 'failed' AND id IS DISTINCT FROM NEW.id;
  IF NEW.status <> 'failed' AND v_refunded + NEW.amount > v_paid THEN
    RAISE EXCEPTION 'Refunds (%) would exceed the payment amount (%)', v_refunded + NEW.amount, v_paid
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER refunds_not_exceed
  BEFORE INSERT OR UPDATE ON refunds
  FOR EACH ROW EXECUTE FUNCTION trg_refunds_not_exceed();

-- ---------------------------------------------------------------------
--  Customer account features (decision 17 — dormant)
-- ---------------------------------------------------------------------

CREATE TABLE saved_posts (
  user_id   bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  post_id   bigint NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  saved_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, post_id)
);

CREATE TABLE followed_sections (
  user_id      bigint   NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  section_id   smallint NOT NULL REFERENCES sections (id) ON DELETE CASCADE,
  followed_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, section_id)
);

CREATE TABLE followed_categories (
  user_id      bigint  NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  category_id  integer NOT NULL REFERENCES categories (id) ON DELETE CASCADE,
  followed_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, category_id)
);
-- =====================================================================
--  09 · Chatbot (18), newsletter (19), messages & notifications (20)
-- =====================================================================

-- ---------------------------------------------------------------------
--  Chatbot knowledge base (decision 18)
-- ---------------------------------------------------------------------

-- An entry either reuses an FAQ (18.4, no duplicate text) or has its own Q/A.
-- Actions are typed FKs instead of a JSON payload.
CREATE TABLE bot_entries (
  id                 integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  faq_id             integer UNIQUE REFERENCES faqs (id) ON DELETE CASCADE,
  question           varchar(300),
  answer             text,
  action_type        varchar(8) NOT NULL DEFAULT 'none'
                     CHECK (action_type IN ('none', 'service', 'page', 'url', 'whatsapp', 'rates', 'weather')),
  action_service_id  integer REFERENCES services (id) ON DELETE RESTRICT,
  action_page_id     integer REFERENCES pages (id) ON DELETE RESTRICT,
  action_url         url_text,
  is_active          boolean NOT NULL DEFAULT true,
  created_by         bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CHECK ((faq_id IS NOT NULL AND question IS NULL AND answer IS NULL)
      OR (faq_id IS NULL AND question IS NOT NULL AND answer IS NOT NULL)),
  CHECK ((action_type = 'service') = (action_service_id IS NOT NULL)),
  CHECK ((action_type = 'page')    = (action_page_id IS NOT NULL)),
  CHECK ((action_type = 'url')     = (action_url IS NOT NULL))
);

CREATE TABLE bot_entry_variants (                         -- other phrasings of the question
  entry_id  integer      NOT NULL REFERENCES bot_entries (id) ON DELETE CASCADE,
  phrase    varchar(300) NOT NULL,
  PRIMARY KEY (entry_id, phrase)
);

CREATE TABLE bot_entry_keywords (
  entry_id  integer     NOT NULL REFERENCES bot_entries (id) ON DELETE CASCADE,
  keyword   varchar(60) NOT NULL,
  PRIMARY KEY (entry_id, keyword)
);

CREATE TABLE bot_quick_replies (                          -- 18.6 buttons
  id                 smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  label_ar           varchar(60) NOT NULL,
  action_type        varchar(8)  NOT NULL
                     CHECK (action_type IN ('entry', 'service', 'page', 'url', 'whatsapp', 'rates', 'weather')),
  target_entry_id    integer REFERENCES bot_entries (id) ON DELETE CASCADE,
  target_service_id  integer REFERENCES services (id) ON DELETE CASCADE,
  target_page_id     integer REFERENCES pages (id) ON DELETE CASCADE,
  target_url         url_text,
  is_root            boolean NOT NULL DEFAULT false,      -- shown when the chat opens
  sort_order         integer NOT NULL DEFAULT 0,
  is_active          boolean NOT NULL DEFAULT true,
  CHECK ((action_type = 'entry')   = (target_entry_id IS NOT NULL)),
  CHECK ((action_type = 'service') = (target_service_id IS NOT NULL)),
  CHECK ((action_type = 'page')    = (target_page_id IS NOT NULL)),
  CHECK ((action_type = 'url')     = (target_url IS NOT NULL))
);

CREATE TABLE bot_entry_quick_replies (                    -- follow-up buttons after an answer
  entry_id        integer  NOT NULL REFERENCES bot_entries (id) ON DELETE CASCADE,
  quick_reply_id  smallint NOT NULL REFERENCES bot_quick_replies (id) ON DELETE CASCADE,
  sort_order      smallint NOT NULL DEFAULT 0,
  PRIMARY KEY (entry_id, quick_reply_id)
);

CREATE TABLE bot_conversations (                          -- 18.9 anonymous
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  public_id     uuid        NOT NULL UNIQUE DEFAULT gen_random_uuid(),
  session_hash  sha256_hex  NOT NULL,
  entry_path    varchar(500),
  started_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX bot_conversations_started_idx ON bot_conversations (started_at);

CREATE TABLE bot_messages (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  conversation_id   bigint       NOT NULL REFERENCES bot_conversations (id) ON DELETE CASCADE,
  role              varchar(4)   NOT NULL CHECK (role IN ('user', 'bot')),
  content           varchar(4000) NOT NULL,
  matched_entry_id  integer REFERENCES bot_entries (id) ON DELETE SET NULL,
  match_score       numeric(5,4) CHECK (match_score BETWEEN 0 AND 1),
  reviewed_at       timestamptz,                         -- 18.10 handled by the admin
  created_at        timestamptz  NOT NULL DEFAULT now(),
  CHECK (role <> 'user' OR char_length(content) <= 500), -- 18.12
  CHECK (role = 'user' OR (match_score IS NULL AND reviewed_at IS NULL))
);
CREATE INDEX bot_messages_conversation_idx ON bot_messages (conversation_id, created_at);
-- "Unanswered questions" queue = user message without a match, not yet reviewed.
CREATE INDEX bot_messages_unanswered_idx ON bot_messages (created_at DESC)
  WHERE role = 'user' AND matched_entry_id IS NULL AND reviewed_at IS NULL;

-- ---------------------------------------------------------------------
--  Newsletter (decision 19) — confirmation codes live in verification_codes
-- ---------------------------------------------------------------------

CREATE TABLE subscribers (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email             email_address NOT NULL UNIQUE,
  name              varchar(120),
  status            varchar(12)   NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'active', 'unsubscribed', 'bounced')),
  source_path       varchar(500),                         -- 19.9 consent proof: where (the page)
  source_placement  varchar(16)   NOT NULL                -- 19.3 / 19.9: which form on that page
                    CHECK (source_placement IN ('footer', 'post_end', 'newsletter_page')),
  consent_ip_hash   sha256_hex,
  subscribed_at     timestamptz   NOT NULL DEFAULT now(), -- 19.9 consent proof: when
  confirmed_at      timestamptz,
  unsubscribed_at   timestamptz,
  brevo_contact_id  varchar(40) UNIQUE,
  updated_at        timestamptz   NOT NULL DEFAULT now(),
  CHECK (status <> 'active'       OR confirmed_at IS NOT NULL),
  CHECK (status <> 'unsubscribed' OR unsubscribed_at IS NOT NULL)
);
CREATE INDEX subscribers_status_idx ON subscribers (status);

CREATE TABLE newsletter_issues (                          -- 19.6 weekly draft
  id                 bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  week_start         date         NOT NULL UNIQUE CHECK (extract(isodow FROM week_start) = 6),  -- Saturday
  subject            varchar(200) NOT NULL,
  intro              text,
  status             varchar(14)  NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'sent_to_brevo', 'sent')),
  brevo_campaign_id  varchar(40),
  sent_at            timestamptz,
  created_by         bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at         timestamptz  NOT NULL DEFAULT now(),
  updated_at         timestamptz  NOT NULL DEFAULT now(),
  CHECK (status = 'draft' OR brevo_campaign_id IS NOT NULL),
  CHECK (status <> 'sent' OR sent_at IS NOT NULL)
);

CREATE TABLE newsletter_issue_posts (
  issue_id    bigint   NOT NULL REFERENCES newsletter_issues (id) ON DELETE CASCADE,
  post_id     bigint   NOT NULL REFERENCES posts (id) ON DELETE RESTRICT,
  sort_order  smallint NOT NULL DEFAULT 0,
  PRIMARY KEY (issue_id, post_id)
);

-- ---------------------------------------------------------------------
--  E-mail, admin notifications, contact form (decision 20)
-- ---------------------------------------------------------------------

CREATE TABLE email_templates (                            -- 20.7 editable texts
  key         varchar(40)  PRIMARY KEY CHECK (key ~ '^[a-z_]+$'),
  name_ar     varchar(80)  NOT NULL,
  audience    varchar(8)   NOT NULL CHECK (audience IN ('visitor', 'admin', 'customer')),
  subject     varchar(200) NOT NULL,
  body_html   text         NOT NULL,
  is_active   boolean      NOT NULL DEFAULT true,       -- dormant templates are inactive
  updated_by  bigint REFERENCES users (id) ON DELETE SET NULL,
  updated_at  timestamptz  NOT NULL DEFAULT now()
);

CREATE TABLE email_log (                                  -- 20.8 / 20.9 (pruned after 90 days)
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  template_key  varchar(40)   NOT NULL REFERENCES email_templates (key) ON DELETE RESTRICT,
  recipient     email_address NOT NULL,
  status        varchar(6)    NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'sent', 'failed')),
  attempts      smallint      NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 3),
  error         varchar(1000),
  queued_at     timestamptz   NOT NULL DEFAULT now(),
  sent_at       timestamptz,
  CHECK (status <> 'sent' OR sent_at IS NOT NULL),
  CHECK (status <> 'failed' OR error IS NOT NULL)
);
CREATE INDEX email_log_queued_idx ON email_log (queued_at);
CREATE INDEX email_log_recipient_idx ON email_log (recipient, queued_at DESC);

CREATE TABLE admin_notifications (                        -- 20.10 bell icon
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id      bigint       NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  category     varchar(10)  NOT NULL
               CHECK (category IN ('security', 'content', 'ads', 'provider', 'system', 'messages')),
  title        varchar(200) NOT NULL,
  body         varchar(1000),
  action_path  varchar(500),
  dedupe_key   varchar(120),                              -- 20.11 same alert max once/hour (checked in app)
  read_at      timestamptz,
  created_at   timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX admin_notifications_unread_idx ON admin_notifications (user_id, created_at DESC) WHERE read_at IS NULL;
CREATE INDEX admin_notifications_dedupe_idx ON admin_notifications (dedupe_key, created_at DESC);

CREATE TABLE contact_messages (                           -- 20.13
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name        varchar(120)  NOT NULL,
  email       email_address NOT NULL,
  phone       phone_e164,
  subject     varchar(200)  NOT NULL,
  message     text          NOT NULL CHECK (char_length(message) BETWEEN 2 AND 5000),
  status      varchar(8)    NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'read', 'archived')),
  ip_hash     sha256_hex,
  handled_by  bigint REFERENCES users (id) ON DELETE SET NULL,
  handled_at  timestamptz,
  created_at  timestamptz   NOT NULL DEFAULT now()
);
CREATE INDEX contact_messages_inbox_idx ON contact_messages (status, created_at DESC);
-- =====================================================================
--  10 · SEO & search (10, 23), analytics (22), audit (22), navigation (21)
-- =====================================================================

-- ---------------------------------------------------------------------
--  SEO and search
-- ---------------------------------------------------------------------

CREATE TABLE redirects (                                  -- 23.6
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  from_path    varchar(500) NOT NULL UNIQUE CHECK (from_path ~ '^/'),
  to_path      varchar(500) CHECK (to_path ~ '^(/|https?://)'),
  status_code  smallint     NOT NULL DEFAULT 301 CHECK (status_code IN (301, 302, 410)),
  hits         bigint       NOT NULL DEFAULT 0 CHECK (hits >= 0),
  last_hit_at  timestamptz,
  created_by   bigint REFERENCES users (id) ON DELETE SET NULL,
  created_at   timestamptz  NOT NULL DEFAULT now(),
  CHECK ((status_code = 410) = (to_path IS NULL)),
  CHECK (to_path IS DISTINCT FROM from_path)
);

-- Synonyms (10.9): each term belongs to exactly one group.
CREATE TABLE synonym_groups (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE synonym_terms (
  term      varchar(80) PRIMARY KEY,
  group_id  integer     NOT NULL REFERENCES synonym_groups (id) ON DELETE CASCADE
);
CREATE INDEX synonym_terms_group_idx ON synonym_terms (group_id);

CREATE TABLE search_terms (                               -- normalised once (10.2)
  id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  normalized_term  varchar(120) NOT NULL UNIQUE
);
CREATE TABLE search_stats_daily (                         -- 10.14
  term_id               bigint  NOT NULL REFERENCES search_terms (id) ON DELETE CASCADE,
  stat_date             date    NOT NULL,
  searches              integer NOT NULL DEFAULT 0 CHECK (searches >= 0),
  zero_result_searches  integer NOT NULL DEFAULT 0 CHECK (zero_result_searches >= 0),
  PRIMARY KEY (term_id, stat_date),
  CHECK (zero_result_searches <= searches)
);
CREATE INDEX search_stats_daily_date_idx ON search_stats_daily (stat_date);

-- ---------------------------------------------------------------------
--  Analytics (decision 22) — daily aggregates only, no raw visitor events
-- ---------------------------------------------------------------------

CREATE TABLE post_views_daily (
  post_id    bigint  NOT NULL REFERENCES posts (id) ON DELETE CASCADE,
  stat_date  date    NOT NULL,
  views      integer NOT NULL DEFAULT 0 CHECK (views >= 0),
  PRIMARY KEY (post_id, stat_date)
);
CREATE INDEX post_views_daily_date_idx ON post_views_daily (stat_date, views DESC);

CREATE TABLE site_stats_daily (
  stat_date        date   PRIMARY KEY,
  page_views       bigint NOT NULL DEFAULT 0 CHECK (page_views >= 0),
  unique_visitors  bigint NOT NULL DEFAULT 0 CHECK (unique_visitors >= 0),   -- 22.2 daily-rotating hash
  CHECK (unique_visitors <= page_views)
);

CREATE TABLE traffic_sources (                            -- 22.6
  code     varchar(12) PRIMARY KEY CHECK (code ~ '^[a-z]+$'),
  name_ar  varchar(40) NOT NULL UNIQUE
);
CREATE TABLE traffic_sources_daily (
  stat_date    date        NOT NULL,
  source_code  varchar(12) NOT NULL REFERENCES traffic_sources (code) ON DELETE RESTRICT,
  visits       bigint      NOT NULL DEFAULT 0 CHECK (visits >= 0),
  PRIMARY KEY (stat_date, source_code)
);

CREATE TABLE device_stats_daily (                         -- 22.7
  stat_date    date       NOT NULL,
  device_type  varchar(7) NOT NULL CHECK (device_type IN ('mobile', 'tablet', 'desktop')),
  visits       bigint     NOT NULL DEFAULT 0 CHECK (visits >= 0),
  PRIMARY KEY (stat_date, device_type)
);

CREATE TABLE event_types (                                -- 22.8
  code     varchar(24) PRIMARY KEY CHECK (code ~ '^[a-z_]+$'),
  name_ar  varchar(60) NOT NULL UNIQUE
);
CREATE TABLE event_stats_daily (
  stat_date   date        NOT NULL,
  event_code  varchar(24) NOT NULL REFERENCES event_types (code) ON DELETE RESTRICT,
  count       bigint      NOT NULL DEFAULT 0 CHECK (count >= 0),
  PRIMARY KEY (stat_date, event_code)
);

CREATE TABLE service_contact_clicks_daily (               -- 14.9
  service_id  integer    NOT NULL REFERENCES services (id) ON DELETE CASCADE,
  channel     varchar(8) NOT NULL CHECK (channel IN ('whatsapp', 'phone', 'email')),
  stat_date   date       NOT NULL,
  clicks      integer    NOT NULL DEFAULT 0 CHECK (clicks >= 0),
  PRIMARY KEY (service_id, channel, stat_date)
);

CREATE TABLE video_plays_daily (
  video_id   bigint  NOT NULL REFERENCES videos (id) ON DELETE CASCADE,
  stat_date  date    NOT NULL,
  plays      integer NOT NULL DEFAULT 0 CHECK (plays >= 0),
  PRIMARY KEY (video_id, stat_date)
);

CREATE TABLE not_found_paths (                            -- 22.10
  path           varchar(500) PRIMARY KEY,
  hits           bigint       NOT NULL DEFAULT 1 CHECK (hits > 0),
  first_seen_at  timestamptz  NOT NULL DEFAULT now(),
  last_seen_at   timestamptz  NOT NULL DEFAULT now(),
  resolved_at    timestamptz,
  CHECK (last_seen_at >= first_seen_at)
);
CREATE INDEX not_found_paths_open_idx ON not_found_paths (hits DESC) WHERE resolved_at IS NULL;

-- Total views per post: derived => materialized view refreshed hourly
-- (REFRESH MATERIALIZED VIEW CONCURRENTLY post_view_totals;)
CREATE MATERIALIZED VIEW post_view_totals AS
SELECT post_id, sum(views)::bigint AS total_views
FROM post_views_daily
GROUP BY post_id;
CREATE UNIQUE INDEX post_view_totals_pk ON post_view_totals (post_id);

-- ---------------------------------------------------------------------
--  Audit log (22.14 – 22.17): append-only
-- ---------------------------------------------------------------------

CREATE TABLE audit_log (
  id             bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  occurred_at    timestamptz NOT NULL DEFAULT now(),
  actor_user_id  bigint REFERENCES users (id) ON DELETE RESTRICT,   -- users are soft-deleted only
  action         varchar(12) NOT NULL CHECK (action IN (
                   'create', 'update', 'delete', 'restore', 'publish', 'unpublish',
                   'login', 'logout', 'settings', 'export')),
  -- Deliberately polymorphic (no FK): the log must survive the deletion of its subject.
  subject_table  varchar(63),
  subject_id     bigint,
  ip_hash        sha256_hex,
  user_agent     varchar(512),
  CHECK ((subject_table IS NULL) = (subject_id IS NULL))
);
CREATE INDEX audit_log_subject_idx ON audit_log (subject_table, subject_id, occurred_at DESC);
CREATE INDEX audit_log_actor_idx   ON audit_log (actor_user_id, occurred_at DESC);
CREATE INDEX audit_log_time_idx    ON audit_log (occurred_at);

CREATE TABLE audit_log_changes (                          -- one row per changed field (before/after)
  audit_id   bigint      NOT NULL REFERENCES audit_log (id) ON DELETE CASCADE,
  field      varchar(63) NOT NULL,
  old_value  text,
  new_value  text,
  PRIMARY KEY (audit_id, field)
);

-- Nobody (not even the admin) can edit or delete audit rows (22.15).
-- The only exception is the scheduled pruning of rows older than 2 years (22.17),
-- which must set: SET LOCAL raqam.audit_prune = 'on';
CREATE FUNCTION trg_audit_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' AND current_setting('raqam.audit_prune', true) = 'on' THEN
    IF TG_TABLE_NAME = 'audit_log' THEN
      IF OLD.occurred_at >= now() - interval '2 years' THEN
        RAISE EXCEPTION 'Audit rows younger than 2 years cannot be pruned' USING ERRCODE = 'check_violation';
      END IF;
    -- audit_log_changes: only together with its (old) parent row; the cascade
    -- runs after the parent is gone, so a still-visible young parent means a direct delete.
    ELSIF EXISTS (SELECT 1 FROM audit_log
                  WHERE id = OLD.audit_id AND occurred_at >= now() - interval '2 years') THEN
      RAISE EXCEPTION 'Audit rows younger than 2 years cannot be pruned' USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'The audit log is append-only (% refused)', TG_OP USING ERRCODE = 'check_violation';
END $$;
CREATE TRIGGER audit_log_append_only
  BEFORE UPDATE OR DELETE ON audit_log
  FOR EACH ROW EXECUTE FUNCTION trg_audit_append_only();
CREATE TRIGGER audit_log_changes_append_only
  BEFORE UPDATE OR DELETE ON audit_log_changes
  FOR EACH ROW EXECUTE FUNCTION trg_audit_append_only();

-- ---------------------------------------------------------------------
--  Navigation and home layout (decision 21)
-- ---------------------------------------------------------------------

CREATE TABLE menus (
  id       smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  key      varchar(16) NOT NULL UNIQUE CHECK (key IN ('header', 'footer_main', 'footer_legal')),
  name_ar  varchar(40) NOT NULL
);

-- A menu link points to exactly one target (typed FKs instead of polymorphism).
CREATE TABLE menu_items (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  menu_id        smallint    NOT NULL REFERENCES menus (id) ON DELETE CASCADE,
  parent_id      integer     REFERENCES menu_items (id) ON DELETE CASCADE,
  label_ar       varchar(60) NOT NULL,
  page_id        integer     REFERENCES pages (id) ON DELETE CASCADE,
  category_id    integer     REFERENCES categories (id) ON DELETE CASCADE,
  section_id     smallint    REFERENCES sections (id) ON DELETE CASCADE,
  url            varchar(500) CHECK (url ~ '^(/|https?://)'),
  opens_new_tab  boolean     NOT NULL DEFAULT false,
  sort_order     integer     NOT NULL DEFAULT 0,
  is_active      boolean     NOT NULL DEFAULT true,
  CHECK (num_nonnulls(page_id, category_id, section_id, url) = 1),
  CHECK (parent_id IS DISTINCT FROM id)
);
CREATE INDEX menu_items_menu_idx ON menu_items (menu_id, parent_id, sort_order);

-- Home page blocks (21.11): typed columns per block type, checked by CHECKs.
CREATE TABLE home_blocks (
  id              smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  block_type      varchar(12) NOT NULL CHECK (block_type IN (
                    'hero', 'breaking', 'latest', 'category', 'section', 'playlist', 'videos',
                    'awareness', 'most_read', 'markets', 'ad', 'newsletter')),
  title_ar        varchar(80),
  category_id     integer     REFERENCES categories (id) ON DELETE CASCADE,
  section_id      smallint    REFERENCES sections (id) ON DELETE CASCADE,
  playlist_id     bigint      REFERENCES playlists (id) ON DELETE CASCADE,
  placement_code  varchar(20) REFERENCES ad_placements (code) ON DELETE CASCADE,
  item_limit      smallint    CHECK (item_limit BETWEEN 1 AND 24),
  sort_order      integer     NOT NULL,
  is_active       boolean     NOT NULL DEFAULT true,
  CHECK ((block_type = 'category') = (category_id IS NOT NULL)),
  CHECK ((block_type = 'section')  = (section_id IS NOT NULL)),
  CHECK ((block_type = 'playlist') = (playlist_id IS NOT NULL)),
  CHECK ((block_type = 'ad')       = (placement_code IS NOT NULL)),
  CONSTRAINT home_blocks_position_uq UNIQUE (sort_order) DEFERRABLE INITIALLY DEFERRED
);
-- =====================================================================
--  11 · Cross-cutting automation
--   a) updated_at trigger on every table that has the column
--   b) an index on every foreign-key column that does not have one yet
--      (PostgreSQL does not index FKs automatically; without it, joins and
--       ON DELETE checks on the parent scan the whole child table)
-- =====================================================================
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT c.table_name
    FROM information_schema.columns c
    JOIN information_schema.tables t
      ON t.table_schema = c.table_schema AND t.table_name = c.table_name
    WHERE c.table_schema = 'public'
      AND c.column_name = 'updated_at'
      AND t.table_type = 'BASE TABLE'
  LOOP
    EXECUTE format(
      'CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION trg_set_updated_at()',
      r.table_name || '_set_updated_at', r.table_name);
  END LOOP;
END $$;

DO $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT c.conrelid::regclass::text AS tbl,
           string_agg(quote_ident(a.attname), ', ' ORDER BY k.ord) AS cols,
           string_agg(a.attname, '_' ORDER BY k.ord) AS col_names
    FROM pg_constraint c
    CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord)
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
    WHERE c.contype = 'f'
      AND c.connamespace = 'public'::regnamespace
      AND NOT EXISTS (
        SELECT 1 FROM pg_index i
        WHERE i.indrelid = c.conrelid
          AND (i.indkey::int2[])[0:cardinality(c.conkey) - 1] @> c.conkey
          AND (i.indkey::int2[])[0:cardinality(c.conkey) - 1] <@ c.conkey)
    GROUP BY c.conrelid, c.conname
  LOOP
    EXECUTE format('CREATE INDEX %I ON %s (%s)',
                   left(r.tbl || '_' || r.col_names || '_fk_idx', 63), r.tbl, r.cols);
  END LOOP;
END $$;
